INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 1, 'Adão, Set, Enós,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 2, 'Cainan, Malaleel, Jared,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 3, 'Henoc, Matusalém, Lamec,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 4, 'Noé, Sem, Cam e Jafet.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 5, 'Filhos de Jafet: Gomer, Magog, Madai, Javan, Tubal, Mosoc, Tiras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 6, 'Filhos de Gomer: Ascenez, Rifat e Togorma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 7, 'Filhos de Javan: Elisa, Tarsis, Cetim e Dodanim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 8, 'Filhos de Cam: Cus, Mesraim, Fut e Canaan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 9, 'Filhos de Cus: Saba, Hevila, Sabata, Regma e Sabataca. Filhos de Regma: Saba e Dadan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 10, 'Cus gerou Neinrod, o qual começou a ser poderoso na terra. Mesraim gerou Ludim, Anamim, Laabim, Neftuim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 12, 'Fetrusim e Casluim, dos quais procederam os Filisteus e os Caftorins.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 13, 'Canaan gerou Sidon, seu primogênito, e também o Heteu,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 14, 'o Jebuseu, o Amorreu, o Gergeseu,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 15, 'o Heveu, o Araceu, o Sineu,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 16, 'e também o Aradiano, o Samareu e o Hamateu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 17, 'Filhos de Sem: Elão, Assur, Arfaxad, Lud, Arão, Hus, Hul, Geter e Mosoc.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 18, 'Arfaxad gerou Sale, o qual depois gerou Heber.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 19, 'Heber teve dois filhos, um dos quais foi chamado Faleg, porque em seu tempo se dividiu a terra; o nome do seu irmão foi Jectan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 20, 'Jectan, gerou Elmodad, Salef, Asarmot, Jare,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 21, 'Adorão, Iluzal, Decla,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 22, 'Hebal, Abimael, Saba,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 23, 'Ofir, Hevila e Jobab. Todos estes eram filhos de Jectan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 24, '(Descendentes de) Sem: Arfaxad, Sale,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 25, 'Heber, Faleg, Ragau,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 26, 'Serug, Nacor, Taré,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 27, 'Abrão, o mesmo que Abraão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 28, 'Filhos de Abraão: Isaac e Ismael.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 29, 'Estas são as suas gerações: Nabaiot, primogênito de Ismael, Cedar, Adbeel, Mabsão,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 30, 'Masma, Duma, Massa, Hadad, Tema,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 31, 'Jetur, Nafis, Cedma. Estes são os filhos de Ismael.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 32, 'Os filhos que Abraão teve de Cetura, sua mulher de segunda ordem, foram: Zamran, Jecsan, Madan, Madian, Jesboc e Sué. Filhos de Jecsan: Saba e Dadan. Filhos de Dadan: Assurim, Latussim e Laomim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 33, 'Os filhos de Madian foram: Efa, Efer, Henoc, Abida e Edaa. Todos estes descenderam de Ceturn.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 34, 'Abraão gerou Isaac, que teve por filhos Esaú e Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 35, 'Filhos de Esaú: Elifaz, Rauel, Jeus, lelom e Coré.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 36, 'Filhos de Elifaz: Temau, Omar, Sef, Gatan, Cenez, Tamna, Amalec.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 37, 'Filhos de Rauel: Naat, Zara, Sama, Meza.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 38, 'Filhos de Seir: Lotan, Sobal, Sebeon, Ana, Dison, Eser, Disan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 39, 'Filhos de Lotan: Hori e Homão; irmã de Lotan: Tamna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 40, 'Filhos de Sobal: Allan, Manaat, Ebal, Sefi e Onam. Filhos de Sebeon: Aia e Ana. Filhos de Ana: Dison.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 41, 'Filhos de Dison: Hamrão, Eseban, Jetran e Caran.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 42, 'Filhos de Eser: Balaão, Zavan, Jacan. Filhos de Disan: Hus e Aran.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 43, 'Os reis que reinaram na terra de Edom, antes que houvesse rei sobre os filhos de Israel, são estes: Bale, filho de Beor, cuja cidade chamava-se Denaba.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 44, 'Morreu Bale, e reinou em seu lugar Jobab, filho de Zaré, de Bosra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 45, 'Depois da morte de Jobab, reinou em seu lugar Husão, do pais dos Temanitas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 46, 'Morreu Husão, e reinou em seu lugar Adad, filho de Badad, que derrotou os Madianitas na terra de Moab; a sua cidade chamava-se Avit.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 47, 'Depois da morte de Adad, reinou em seu lugar Semla de Masreca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 48, 'Semla morreu, e reinou em seu lugar Saul de Roobot, que está situada junto do rio (Eufrates).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 49, 'Morto Saul, reinou em seu lugar Balanan, filho de Acobor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 50, 'Balanan morreu, e reinou em seu lugar Adad, cuja cidade se chamava Fau; sua mulher chamava-se Meetabel, filha de Matred, que era filha de Mezaab.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 51, 'Morto Adad, houve em Edom governadores (ou juízes) em lugar de reis; o governador Tamna, o governador Alva, o governador Jetet,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 52, 'o governador Oolibama, o governador Ela, o governador Finon'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 53, 'o governador Cenez, o governador Temau, o governador Mabsar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 54, 'o governador Magdiel, o governador Hirão. Estes foram os governadores de Edom.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 1, 'Os filhos de Israel foram: Ruben, Simeão, Levi, Judá, Issacar, Zabulon,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 2, 'Dan, José, Benjamin, Neftali, Gad e Aser.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 3, 'Filhos de Judá: Her, Onan e Sela; estes três nasceram da filha de Sué, a Cananeia. Her, primogênito de Judá, foi mau diante do Senhor, e o Senhor fê-lo morrer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 4, 'Tamar, nora de Judá, deu-lhe à luz Farés e Zara. Todos os filhos de Judá foram pois cinco.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 5, 'Filhos de Farés: Hesron e Hamul.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 6, 'Filhos de Zara: Zamri, Etan, Eman, Calcai e Dara, cinco a o todo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 7, 'Filhos de Carmi: Acar, que turbou Israel e pecou num furto de coisa votada anátema.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 8, 'Filho de Etan: Azarias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 9, 'Os filhos que nasceram de Hesron (foram): Jerameel, Ram e Calubi.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 10, 'Ram gerou Aminadab, Aminadab gerou Naasson príncipe dos filhos de Judá;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 11, 'Naasson gerou Salma, do qual procedeu Booz;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 12, 'Booz gerou Obed, o qual gerou Isaí;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 13, 'Isaí teve por primogênito a Ellab, sendo seu segundo (filho) Abinadab, terceiro Simaa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 14, 'quarto Natanael, quinto Radal,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 15, 'sexto Asom, sétimo Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 16, 'Foram irmãs destes Sarvla e Abigall. Os filhos de Sarvia (foram) três; Abisai, Joab e Asael.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 17, 'Abigall gerou Amasa, cujo pai foi Jeter Ismaelita.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 18, 'Caleb, filho de Hesron, teve filhos de sua mulher Azuba, assim como de Jeriot. Os filhos de Azuba foram: Jaser, Sobab e Ardon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 19, 'Tendo morrido Azuba, Caleb tomou por mulher Efrata, da qual teve Hur.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 20, 'Hur gerou Uri; Uri gerou Bezeleel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 21, 'Depois Hesron tomou por mulher a filha de Maquir pai de Galaad; recebeu-a, tendo sessenta anos, e teve dela Segub.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 22, 'Segub também gerou Jair, o qual foi senhor de vinte e três cidades na terra Galaad.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 23, 'Gessur e Arão tomaram as cidades de Jair, assim como Canat, com as suas aldeias, sessenta cidades. Todos estes eram filhos de Maquir, pai de Galaad.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 24, 'Depois da morte de Hesron, em Caleb-Efrata, Abia, mulher de Hesron, deu-lhe à luz Azur, pai de Técua.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 25, 'A Jerameel, primogênito de Hesron, nasceram os filhos: Ram, primogênito, Buna, Arão, Ason e Aquia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 26, 'Jerameel também casou com outra mulher chamada Atara, que foi mãe de Onam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 27, 'Bam, primogênito de Jerameel, teve por filhos a Moos, a Jamim e a Acar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 28, 'Onam teve por filhos a Semei e a Jada. Os filhos de Semei foram: Nadab e Abisur.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 29, 'A mulher de Abisur chamava-se Abiail, a qual lhe deu à luz Aoban e Molid.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 30, 'Os filhos de Nadab foram Saled e Afaim. Saled morreu sem filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 31, 'Afaim teve um filho chamado Jesi, o qual Jesi gerou Sesan. Sesan gerou Oolai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 32, 'Os filhos de Jada, irmão de Semei, foram: Jeter e Jonatan. Jeter morreu sem filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 33, 'Jonatan gerou Falet e Ziza. Estes foram os filhos de Jerameel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 34, 'Sesan não teve filhos, mas sòmente filhas; (tomou) um escravo egípcio, chamado Jeraa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 35, 'a quem deu por mulher uma sua filha, a qual lhe deu à luz Etei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 36, 'Etei gerou Natan, e Natan gerou Zabad;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 37, 'Zabad gerou Oflal, e Oflal gerou Obed;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 38, 'Obed gerou Jeú; Jeú gerou Azarias;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 39, 'Azarias gerou Heles; Heles gerou Elasa:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 40, 'Elasa gerou Sisamoi; Sisamoi gerou Selum;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 41, 'Selum gerou Icamia, e Icamia gerou Elisama.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 42, 'Os filhos de Caleb, irmão de Jerameel, foram Mesa, seu primogênito, que foi pai de Zif, e os descendentes de Maresa, pai de Hebron.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 43, 'Filhos de Hebron: Coré, Tafua, Recem e Sama.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 44, 'Sarna gerou Raão, pai de Jercaão; Recera gerou Samai;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 45, 'Samai teve um filho, chamado Maou; Maon foi pai de Betsur.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 46, 'Efa, mulher de segunda ordem de Caleb, deu à luz Haran, Mosa e Gezez. Haran gerou Gezez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 47, 'Filhos de Joadai: Regom, Joatan, Gesan, Falet, Efa e Saaf.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 48, 'Maaca, mulher de segunda ordem de Caleb, deu à luz Saber e Tarana.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 49, 'Ela deu também à luz Saaf, pai de Madmena, e Sue, pai de Maquebena e pai de Gabaa. Acsa foi filha de Caleb.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 50, 'Filhos de Caleb, filho de Hur, primogênito de Efrata, foram estes: Sobal, pai de Cariatiarim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 51, 'Salma. pai de Belém, Harif, pai de Betgader.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 52, 'Sobal, pai de Cariatiarim, teve por filhos Haroé, Hatsi-Hamme-nuhoth.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 53, 'As famílias que eles fundaram em Cariatiarim foram: os Jetreus, os Afuteus, os Semateus e os Masereus. Destes procederam os Saraítas e os Estaolitas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 54, 'Filhos de Salma: Belém e os Netofatlanos, Ataroth-Beth-Joab, metade dos Manaquitianos, os Saraítas, (foi) dos descendentes de Sarai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 55, 'e também as famílias dos escribas, que habitavam em Jabes: Os Tiriatianos, os Squimatianos e os Sucatianos. Estes são os Cinens, que descendem de Hamath, pai da casa de Recab.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 1, 'Davide teve estes filhos, que lhe nasceram em Hebron: o primogênito Amnon, de Aquinoam Jezraelita; o segundo, Daniel, de Abigail do Carmelo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 2, 'o terceiro, Absalão, filho de Maaca, filha de Tolmal, rei de Gessur: o quarto, Adonias, filho de Agit;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 3, 'o quinto, Safatias, filho de Abital; o sexto, Jetraão, filho de Egla, sua mulher.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 4, 'Nasceram-lhe, portanto, seis filhos em Hebron, onde ele reinou durante sete anos e seis meses. Em Jerusalém reinou durante trinta e três anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 5, 'Em Jerusalém nasceram-lhe estes fllhos: Simaa, Sobab, Natan e Salomão, todos quatro de Betsabé, filha de Amiel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 6, 'Teve mais Jebaar, Elisama,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 7, 'Elifalet, Noge, Nefeg, Jafia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 8, 'e também Elisama, Eliada, Elifelet: nove ao todo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 9, 'Todos estes foram os filhos de Davide, sem contar os filhos das mulheres de segunda ordem. Tiveram uma irmã chamada Tamar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 10, 'O filho de Salomão foi Roboão, cujo filho Abia gerou Asa. Deste nasceu Josafat,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 11, 'pai de Jorão; Jorão gerou Ocozias, do qual nasceu Joás;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 12, 'Amasias, filho deste, gerou Azarias; Joatão, filho de Azarias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 13, 'gerou a Acaz, pai de Ezequias, de quem nasceu Manassés;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 14, 'Manassés gerou Amon, pai de Josias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 15, 'Os filhos de Josias foram: Joanan, o primogênito, o segundo Joaquim, o terceiro Sedecias, o quarto Selum.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 16, 'De Joaquim nasceram Jeconias e Sedecias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 17, 'Filhos de Jeconias foram: Asir, Salatiel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 18, 'Melquiron, Fadaia, Seneser, Jacemin, Sama e Nadabia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 19, 'De Fadaia nasceram Zorobabel e Semei. Zorobabel gerou Mosolão, Hananias, e Salomit, irmã deles,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 20, 'e também estes cinco: Hasaban, Ool, Baraquias, Hasadias e Josahesed.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 21, 'Hananias teve por filho a Faltlas, pai de Jeseias, cujo filho foi Rafaia; o filho deste foi Arnan, do qual nasceu Obdia, cujo filho foi Secenlas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 22, 'O filho de Secenias foi Semeia, do qual foram filhos Hatus, Jegaal, Baria, Naaria e Safat, em número de seis (contando o pai).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 23, 'Os filhos de Naaria foram três: Elioenai, Ezequias e Ezricão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 24, 'Os filhos de Elloenai foram sete: Odulia, Eliasub, Feleia, Acub, Joanan, Dalaia e Anani.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 1, 'Filhos (ou descendentes) de Judá foram: Farés, Hesron, Carmi, Hur e Sobal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 2, 'Raias, filho de Sobal, gerou Jaat, de quem nasceram Aumal e Laad. Estas são as famílias dos Saratitas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 3, 'Estes são os descendentes do pai de Etão: Jezrael, .Joseina e Jedebos, que tiveram uma irmã chamada Asalelfuni.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 4, 'Fanuel foi pai de Gedor, e Ezer pai de Hosa. Estes são os filhos de Hur, primogênito de Efrata, pai de Belém,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 5, 'Assur, pai de Tecua, teve duas mulheres: Halaa e Naara.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 6, 'De Naara teve Oozão, Hefer, Temamos e Aastari; estes são os filhos de Naara.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 7, 'Os filhos de Halaa foram: Seret, Isaar e Etnan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 8, 'Cós gerou Anob, Soboba e a família de Aareel, filho de Arum'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 9, 'Jabes foi mais ilustre do que seus irmãos, e sua mãe pôs-lhe o nome de Jabes, dizendo: Porque o dei à luz com dor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 10, 'Jabes invocou o Deus de Israel, dizendo: Oh! Se tu me cumulasses de bênçãos e dilatasses os meus limites, se a tua mão fosse comigo, e não permitisses que eu fosse oprimido pela malícia!... E Deus concedeu-lhe o que ele pediu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 11, 'Caleb, irmão de Sua, gerou Maír, que foi pai de Eston.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 12, 'Eston gerou Betrafa, Fess e Teina, pai dos habitantes da cidade de Naas. Estes são os povoadores de Reca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 13, 'Filhos de Cenez: Otoniel e Saraia. Filhos de Otoniel: Hatat e Maonati.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 14, 'Maonati gerou Ofra, Saraia gerou Joab, pai dos habitantes do Vale dos Artífices, (assim chamado) porque ali habitavam os artífices.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 15, 'Os filhos de Caleb, filho de Jefone, foram: Hir, Ela e Naão. Filho de Ela: Cenez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 16, 'Os filhos de Jeleleel, foram: Zif, Zifa, Tiria e Asrael.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 17, 'Os filhos de Ezra foram: Jeter, Mered, Efer e Jalon. A mulher de Mered (a egípcia) deu à lua Myriam, Sammai, e Jesba, pai dos habitantes de Estamo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 18, '(Outra) sua mulher, Odala, deu à luz Jared, pai de Gedor, e Heber, pai de Soco, e Icutiel, pai de Zanoe. Estes são os filhos de Betia, filha de Faraó, com a qual casou Mered.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 19, 'Os filhos de (sua) mulher Odala, irmã de Naão, pai de Ceila, foram: Garmi e Estamo, que era de Macati.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 20, 'Os filhos de Simão foram: Amnon, Binna, filho de Hanan, e Tilon. Os filhos de Jesi foram: Zoet e Benzoet.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 21, 'Os filhos de Sela, (terceiro) filho de Judá, foram: Her, pai de Leca, Laada, pai de Meresa, e as famílias da casa dos fabricantes de linho fino na casa do juramento,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 22, 'e Joaquim (cujo nome significa) o que fez parar o sol, e os habitantes de Cozeba (isto é) os homens da Mentira, e Joás e Saraf (isto é) o Afouto e o Ardente, que foram príncipes em Moab e Laem. Estas memórias são antigas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 23, 'Estes são os oleiros que habitavam nas hortas e nos cercados, nas casas do rei: trabalhando para ele, ali moravam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 24, 'Os filhos de Simeão foram: Namuel, Jamin, Jarib, Zara, Saul.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 25, 'Selum, seu filho, foi pai de Mabsão, o qual teve por filho a Masma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 26, 'Filhos de Masma: Hamuel, de quem foi filho Zacur, do qual foi filho Semei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 27, 'Semei teve dezasseis filhos e seis filhas, mas seus irmãos não tiveram muitos filhos, e toda a sua posteridade não pode igualar o número dos filhos de Judá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 28, 'Habitaram em Bersabé, em Molada, em Hasarsual,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 29, 'em Bata, em Asom, em Tolad,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 30, 'em Batuel, em Horma, em Siceleg,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 31, 'em Betmarcabot, em Hasarsusim, em Betberal e em Saarim. Estas foram os suas cidades até ao reinado de Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 32, '(Tinham também): Etão, Aen, Remon, Toquen e Asan, cinco cidades,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 33, 'com todas as aldeias dos seus arredores, até Baal. Esta é a sua habitação e o seu registo genealógico.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 34, 'Mosabab, Jemlec, Josa, filho de Amasias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 35, 'Joel, Jeú, filho de Josabia, filho de Saraia, filho de Asiel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 36, 'Elioenai, Jacoba, Isuaia, Asaia, Adlel, Ismiel, Banaia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 37, 'Ziza, filho de Sefei, filho de Alon, filho de Idaia, filho de Semri, filho de Samaia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 38, 'Estes são os príncipes ilustres nas suas famílias, e multiplicaram-se em extremo as suas casas patriarcais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 39, '(Por isso) saíram a fim de ocupar Gadôr até no oriente do vale, em busca de pastos para os seus gados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 40, 'Encontraram pastagens abundantes e muito excelentes, e uma terra espaçosíssima, tranquila e fértil, onde antes tinham habitado os descendentes de Cam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 41, 'Estes pois, que acima nomeamos, vieram no tempo de Ezequias, rei de Judá; deitaram abaixo as suas tendas, mataram os habitantes que ali encontraram, destruindo-os (assim) até ao dia de hoje; habitaram em lugar deles, porque encontraram abundantíssimos pastos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 42, 'Igualmente quinhentos homens dos filhos de Simeão passaram ao monte de Seir, tendo por chefes a Faltias, Naarias, Rafaias e Oziel, filhos de Jezl,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 43, 'e acabaram com os restos dos Amalecitas, que tinham podido salvar-se, ficando a habitar ali, em seu lugar, até ao dia de hoje.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 1, 'Eis os filhos de Ruben, primogênito de Israel (porque este foi o seu primogênito, em bora, por ter manchado o tálamo de seu pai, fosse o seu direito de primogenitura dado aos filhos de José, filho de Israel, deixando (desta forma) Ruben de ser considerado primogênito; quanto a Judá, que era o mais valente de todos os seus irmãos, da sua estirpe saíram príncipes, mas o direito da primogenitura foi adjudicado a José).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 3, 'Eis, pois os filhos de Ruben, primogênito de Israel: Enoc, Falu, Esron e Carmi.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 4, 'Filho de Joel: Samia, pai de Gog, cujo filho foi Semei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 5, 'Mica, foi filho de Semei; Rela, filho de Mica; Baal, filho de Rela;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 6, 'Beera, filho de Baal, a quem Telgatfaluasar, rei dos Assírios, levou cativo, e que foi príncipe na tribo de Ruben.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 7, 'Os seus irmãos e toda a sua parentela, quando se fez a lista deles por famílias, tiveram por príncipes a Jeiel e Zacarias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 8, 'Bala, filho de Azaz, filho de Sama, filho de Joel, estabeleceu-se em Aroer, até Nebo e Beelmeou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 9, 'Habitou também para o oriente, até à entrada do deserto e até ao rio Eufrates, porque possuia grande quantidade de gado na terra de Galaad.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 10, 'No reinado de Saul (os seus descendentes) pelejaram contra os Agareus, mataram-nos, e habitaram em lugar deles nas suas tendas, em todo o território que olhava para o oriente de Galaad.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 11, 'Os filhos, porém, de Gad, estabeleceram-se defronte deles, no país de Basan até Selca;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 12, 'Joel era o chefe, Safan o segundo, e em seguida Janai e Safar, em Basan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 13, 'Os seus irmãos, segundo as casas de suas parentelas, eram: Miguel, Mosolão, Sebe, Jorai, Jacan, Zie e Heber, ao todo sete.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 14, 'Estes foram filhos de Abiail, filho de Uri, filho de Jara, filho de Galaad, filho de Miguel, filho de Jesesi, filho de Jedo, filho de Buz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 15, 'Foram também seus irmãos os filhos de Abdiel, filho de Guni, chefe das suas casas patriarcais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 16, 'Habitaram em Galaad e em Basan, nas aldeias e em todos os subúrbios de Saron, dum extremo ao outro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 17, 'Todos estes foram contados no tempo de Joatão, rei de Judá, e no tempo de Joroboão, rei de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 18, 'Os filhos de Ruben, de Gad e da meia tribo de Manassés, foram homens muito guerreiros, que traziam escudos e espadas, que manejavam o arco, hábeis para a guerra, em número de quarenta e quatro mil setecentos e sessenta, que marchavam a combater.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 19, 'Fizeram guerra contra os Agareus, mas os Itureus, os de Nafis e de Nodab,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 20, 'prestaram-lhes auxílio. Foram entregues nas suas mãos os Agareus e todos os que os tinham auxiliado, porque invocaram a Deus quando pelejavam, e ele ouviu-os, porque tinham confiado nele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 21, 'Apoderaram-se de tudo o que possuíam: de cinquenta mil camelos, duzentas e cinquenta mil ovelhas, dois mil jumentos e cem mil pessoas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 22, 'Houve muitos mortos, porque foi guerra (feita com o auxílio) do Senhor. Habitaram em seu lugar até à transmigração (para Babilónia).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 23, 'Também os filhos da meia tribo de Manassés possuíram as terras desde os confins de Basan até Baal, Hermon, Sanir e o monte de Hermon, porque eram em grande número.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 24, 'Os chefes das casas das suas linhagens foram Efer, Jesi, Eliel, Ezriel, Jeremias, Odoias e Jediel, homens fortíssimos e possantes, famosos, chefes das suas famílias patriarcais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 25, 'Abandonaram, porém, o Deus de seus pais, e prostituiram-se seguindo os deuses dos povos da terra, que Deus exterminou diante deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 26, 'Por isso Deus de Israel suscitou o espírito de Ful, rei dos Assírios, e o espírito de Telgatfalnasar, rei de Assur, que transportou a tribo de Ruben, a tribo de Gad e a meia tribo de Manassés para Laela, para Habor, para Ara e para o rio Gozan, até ao dia de hoje.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 1, 'Filhos de Levi: Gereon, Caat e Merari.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 2, 'Filhos de Caat: Amrão, Isaar, Hebron e Oziei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 3, 'Filhos de Amrão: Arão, Moisés e Alaria. Filhos de Arão: Nadab e Abiu, Eleazar e Itamar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 4, 'Eleazar gerou Fineias, e Fineias gerou Abisué;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 5, 'Abisué gerou Boci, e Boci gerou Ozi;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 6, 'Ozi gerou Zaraias, e Zaraias gerou Meraiot;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 7, 'Meraiot gerou Amarias, e Amarias gerou Aquitob;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 8, 'Aquitob gerou Sadoc, e Sadoc gerou Aquimaas;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 9, 'Aquimaas gerou Azarias, e Azarias gerou Joanan;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 10, 'Joanan gerou Azarias, que é aquele que exerceu o sacerdócio no templo que Salomão tinha fundado em Jerusalém;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 11, 'Azarias gerou Amarias, e Amarias gerou Aquitob;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 12, 'Aquitob gerou Sadoc, e Sadoc gerou Selum;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 13, 'Selum gerou Helcias, e Helcias gerou Azarias;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 14, 'Azarias gerou Saraias, e Saraias gerou Josedec.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 15, 'Josedec deixou a sua pátria, quando o Senhor transferiu o povo de Judá e de Jerusalém por meio de Nabucodonosor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 16, 'Os filhos de Levi foram: Gerson, Caat e Merari.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 17, 'Estes são os nomes dos filhos de Gerson; Lobni e Semei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 18, 'Filhos de Caat: Amrão, Isaar, Hebron e Oziei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 19, 'Filhos de Merari: Mooli e Musi. Eis os descendentes de Levi segundo as suas famílias:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 20, 'De Gerson foi filho Lobni, de Lobni Jaat, de Jaat Zama,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 21, 'de Zama Joú, de Joá Ado, de Ado Zara, de Zara Jetrai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 22, 'Filhos de Caat: Aminadab, seu filho, Coré, filho de Aminadab, Asir de Coré,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 23, 'Elcana de Asir, Abiasaf de Elcana, Asir de Ablasaf,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 24, 'Taat de Asir, Uriel de Taat, Ozias de Uriel, Saul de Ozias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 25, 'Filhos de Elcana: Amasai, e Aquimot,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 26, 'Elcana, seu filho, Sofai, seu filho, Naat, seu filho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 27, 'Eliab, seu filho, Jeroão seu filho, Elcana, seu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 28, 'Filhos de Samuel: Vasseni, primogênito, e Abia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 29, 'Filhos de Merari: Mooli, Lobni, filho deste, Semei, filho de Lobni, Oza, filho de Semei,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 30, 'Samaa, filho de Oza, Hagia, filho de Samaa, Asaia, filho de Hagia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 31, 'Eis aqueles que Davide constituiu sobre os cantores da casa do Senhor, depois que a arca foi colocada (em Jerusalém):'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 32, 'cantando, ministraram diante do tabernáculo do testemunho, até que Salomão edificou a casa do Senhor em Jerusalém, e exerceram o seu ministério segundo o seu turno.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 33, 'Eis os que serviam juntamente com seus filhos: Dos filhos de Caat: Heman cantor, filho de Joel, filho de Samuel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 34, 'filho de Elcana, filho de Jeroão, filho de Eliel, filho de Tou,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 35, 'filho de Suf, filho de Elcana, filho de Maat, filho de Amasai,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 36, 'filho de Elcana, filho de Joel, filho de Azarias, filho de Sofonias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 37, 'filho de Taat, filho de Asir, filho de Abiasaf, filho de Coré,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 38, 'filho de Isaar, filho de Caat, filho de Levi, filho de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 39, 'Seu irmão Asaf, que estava à sua direita, e que era filho de Baraquias, filho de Samaa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 40, 'filho de Miguel, filho de Basaia, filho de Melquia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 41, 'filho de Atanai, filho de Zara, filho de Adaia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 42, 'filho de Etan, filho de Zama, filho de Semei,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 43, 'filho de Jet, filho de Gerson, filho de Levi.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 44, 'Seus irmãos, filhos de Merari, estavam à esquerda: Etan, filho de Cusi, filho de Abdi, filho de Maloc,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 45, 'filho de Hasabias, filho de Amasias, filho de Helcias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 46, 'filho de Amasai, filho de Boni, filho de Somer,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 47, 'filho de Mooli, filho de Musi, filho de Merari, filho de Levi.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 48, 'Os Levitas, seus irmãos, foram destinados para todo o serviço do tabernáculo da casa do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 49, 'Porém Aarão e seus filhos queimavam as vítimas sobre o altar dos holocaustos e sobre o altar dos perfumes, (ocupando-se) em tudo o que dizia respeito ao Santo dos Santos, e oravam por Israel, seguindo tudo o que Moisés, servo do Senhor, tinha prescrito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 50, 'Os filhos de Aarão são estes: Eleazar, seu filho, Fineias, filho de Eleazar, Abisué, filho de Fineias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 51, 'Boci, filho de Abisué, Ozi, filho de Boci, Zaraia, filho de Ozi,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 52, 'Meraiot, filho de Zaraia, Amarias, filho de Meraiot, Aquitob, filho de Amarias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 53, 'Sadoc, filho de Aquitob, Aquimaas, filho de Sadoc.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 54, 'Estas são as suas habitações pelas povoações e arredores, isto é, as habitações dos filhos de Aarão, segundo as famílias dos Caatitas, que lhes tinham tocado por sorte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 55, 'Foi-lhes, pois, dada Hebron na terra de Judá, e os subúrbios que a rodeiam;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 56, 'os campos, porém, da cidade e as aldeias foram dados a Caleb, filho de Jefone.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 57, 'Foram, pois dadas aos filhos de Arão: Hebron, cidade de refúgio, Lobna, com os seus subúrbios,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 58, 'Jeter e Estemo, com os seus subúrbios, Helon e Dabir, com os seus subúrbios,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 59, 'Asan e Betesemes, com os seus subúrbios;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 60, 'da tribo de Benjamim deram-lhes: Gabee com os seus subúrbios, Almat com os seus subúrbios, Anatot com os seus subúrbios: ao todo treze cidades repartidas entre as suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 61, 'Aos filhos de Caat, que restavam da sua família, foram dadas em possessão dez cidades da meia tribo de Manassés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 62, 'Aos filhos de Gerson, segundo as suas famílias, foram dadas treze cidades da tribo de Issacar, da tribo de Aser, da tribo de Neftali e da tribo de Manassés, em Basan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 63, 'Aos filhos de Merari, segundo as suas famílias, foram dadas à sorte doze cidades da tribo de Ruben, da tribo de Gad e da tribo de Zabulon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 64, 'Deram os filhos de Israel aos Levitas estas cidades com os seus subúrbios;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 65, 'deram-lhes por sorte estas cidades, da tribo dos filhos de Judá, da tribo dos filhos de Simeão e da tribo dos filhos de Benjamim, as quais designaram pelos seus próprios nomes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 66, 'Quanto aos que eram da parentela dos filhos de Caat, as cidades do seu domínio foram da tribo de Efraim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 67, 'Deram-lhes as cidades de refúgio: Siquem com os seus subúrbios sobre o monte de Efraim, Gazer com os seus subúrbios,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 68, 'Jecmaam com os seus subúrbios, e da mesma sorte Betoron,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 69, 'e também Helon com os seus subúrbios, e Getremon da mesma maneira.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 70, 'Da meia tribo de Manassés, deram Aner, com os seus subúrbios, e Balaão, com os seus subúrbios, àqueles que ainda restavam da linhagem dos filhos de Caat.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 71, 'Aos filhos de Gerson deram da meia tribo de Manassés: Gaulon em Basan, com os seus subúrbios, e Astarot com os seus subúrbios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 72, 'Da tribo de Issacar (deram-lhes): Cedes com os seus subúrbios, Daberet com os seus subúrbios,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 73, 'Ramot com os seus subúrbios, Anem com os seus subúrbios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 74, 'Da tribo de Aser: Masal com os seus subúrbios, e igualmente Abdon'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 75, 'e Hucac com os seus subúrbios, e Roob com os seus subúrbios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 76, 'Da tribo de Neftali: Cedes na Galilén com os seus subúrbios, Hamon com os seus subúrbios, Cariataim com os seus subúrbios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 77, 'Aos filhos de Merari, que ainda restavam, (deram) da tribo de Zabulon: Remono com os seus subúrbios, e Tabor com os seus subúrbios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 78, 'Da banda de além do Jordão, defronte de Jericó, ao oriente do Jordão, deram da tribo de Ruben: Bosor no deserto com os seus subúrbios, Jassa com os seus subúrbios,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 79, 'Cademot com os seus subúrbios, Mefaat com os seus subúrbios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 80, 'Além disso, (deram-lhes) da tribo de Gad: Ramot em Galaad com os seus subúrbios, Manaim com os seus subúrbios,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 81, 'Hesebon com os seus subúrbios, Jezer com os seus subúrbios.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 1, 'Os filhos de Issacar foram quatro: Tola, Fua, Jasub e Simeron.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 2, 'Os filhos de Tola foram: Ozi, Rafala, Jeriel, Jemai, Jebsem e Samuel, que foram chefes das casas das suas linhagens. Da linhagem de Tola foram contados, no tempo de Davide, vinte e dois mil e seiscentos homens valorosíssimos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 3, 'Filhos de Ozi: Izraia, do qual nasceram Miguel, Obadin, Joel e Jesia: ao todo, cinco chefes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 4, 'Com eles havia em seus ramos e famílias trinta e seis mil homens fortíssimos e adestrados para combater, porque tiveram muitas mulheres e filhos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 5, 'Dos seus irmãos, em toda a casa de Issacar, contaram-se oitenta e sete mil combatentes valorosíssimos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 6, 'Os filhos de Benjamim foram três: Bela, Becor e Jadiel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 7, 'Os filhos de Bela foram: Esbon, Ozi, Oziei, Jerimot e Urai, cinco chefes de famílias, homens valentíssimos para o combate, cujo número foi de vinte e dois mil e quatrocentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 8, 'Filhos de Becor: Zamira, Joás, Eliezer, Elioenai, Amri, Jerimot, Abla, Anatot e Almat: todos estes foram filhos de Becor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 9, 'Foram contados nas suas famílias pelos ramos das suas linhagens vinte mil e duzentos homens valorosíssimos para a guerra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 10, 'Filho de Jadiel: Balan. Filhos de Balan: Jeús, Benjamim, Aod, Canana, Zetau, Tarsis e Abisaar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 11, 'Todos estes filhos de Jadiel foram chefes de casas patriarcais, homens muito valorosos, em número de dezassete mil e duzentos, adestrados para a guerra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 12, 'Sefão e Hafão foram filhos de Hir; e Hasim foi filho de Aer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 13, 'Os filhos de Neftali foram: Jasiel, Guni, Teser e Selum, que descendiam de Bala.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 14, 'Esrael foi filho de Manassés; uma siríaca, sua mulher de segunda ordem, deu à luz Maquir, pai de Galaad.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 15, 'Maquir tomou mulher de Hafim e Safan. Teve uma irmã chamada Maaca. O nome do segundo filho foi Salfaad, e Salfaad teve só filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 16, 'Maaca, mulher de Maquir, deu à luz um filho, ao qual pôs o nome de Fares; seu irmão chamou-se Sares, cujos filhos foram Ulão e Recen.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 17, 'O filho de Ulão foi Badan. Estes são os filhos de Galaad, filho de Maquir, filho de Manassés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 18, 'Sua irmã Regma deu à luz Isod (que significa) varão formoso, Abiezer e Moola.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 19, 'Os filhos de Semida foram: Ain, Sequem, Leci e Anião.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 20, 'Os filhos de Efraim foram: Sutala, Bared, seu filho, Taat, seu filho, Elada, seu filho, Taat, seu filho, Zabad, seu filho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 21, 'Sutala, seu filho, Ezer e Elad. Os habitantes de Get mataram (a Ezer e Elad) por eles terem ido invadir as suas possessões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 22, 'Chorou-os Efraim, seu pai, durante muitos dias, e seus irmãos foram para o consolar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 23, 'Depois juntou-se com sua mulher, e ela concebeu e deu à luz um filho, a que pôs o nome de Béria, por ter nascido no meio das aflições da sua família.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 24, 'A sua filha foi Sara, que reedificou a alta e a baixa Betoron, e Ozensara.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 25, 'Foram seus filhos Rafa e Resef; Tale, seu filho, Taan, seu filho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 26, 'Laadan, seu filho, Amiud, seu filho, Elisama, seu filho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 27, 'Nun, seu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 28, 'As suas possessões e a sua morada foram: Betei com as suas dependências, Noran do lado do oriente, Gazer com o que lhe pertence do lado do ocidente, Siquem com as suas dependências, até Aza com as suas dependências.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 29, 'Nos confins dos filhos de Manassés tiveram: Betsan com as suas dependências, Tanac com as suas dependências, Magedo com as suas dependências, Dor com suas dependências. Nestes lugares habitaram os filhos de José, filho de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 30, 'Os filhos de Aser foram: Jemna, Jesua, Jessui, Baria, e Sara, sua irmã.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 31, 'Filhos de Baria: Heber e Melquiel; este é o pai de Barsait.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 32, 'Heber gerou Jeflat, Somer, Hotão, e Sun, sua irmã.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 33, 'Filhos de Jeflat: Fosec, Camaal e Asot: estes foram os filhos de Jeflat.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 34, 'Filhos de Somer: Ai, Roaga, Haba e Arão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 35, 'Filhos de Helem, seu irmão: Sufa, Jemna, Seles e Amai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 36, 'Filhos de Sufa: Sué, Harnafer, Sual, Beri, Janra,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 37, 'Bosor, Hod, Sama, Salusa, Jetran e Bera.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 38, 'Filhos de Jeter: Jefone, Fasfa e Ara.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 39, 'Filhos de Ola: Aree, Haniel e Resia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 40, 'Todos estes foram filhos de Aser, chefes de casas patriarcais, homens distintos e valorosíssimos, chefes de príncipes, registrados no número de vinte e seis mil, capazes de tomar armas.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 1, 'Benjamim gerou Bela, seu primogênito, Asbel, segundo, Aara, o terceiro,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 2, 'Noaa, o quarto, e Rafa, o quinto,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 3, 'Os filhos de Bela foram: Adar, Gera, Ablud,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 4, 'Abisué, Naaman, Aoé,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 5, 'Gera, Sefufan e Hurão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 6, 'Estes são os filhos de Aod, chefes das famílias que habitaram em Gabaa, e que foram transportados para Manaat;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 7, 'Naaman, Aquia e Bera; este foi o que os transportou, e que gerou Oza e Alud.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 8, 'Saaraim teve filhos no país de Moab, depois que repudiou Husim e Bara, suas mulheres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 9, 'De Hodes, sua mulher, teve Jobab, Sébia, Mosa, Molcom,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 10, 'Jeús, Sequia e Marma; estes foram os seus filhos, chefes de suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 11, 'De Husim teve Abitob e Elfaal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 12, 'Filhos de Elfaal: Heber, Misaão e Samad; este fundou Ono e Lod com as suas dependências.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 13, 'Baria e Sama, chefes das famílias que se estabeleceram em Aialon, puseram em fuga os habitantes de Get.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 14, 'Aio, Sesac, Jerimot,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 15, 'Zabadia, Arod, Heder,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 16, 'Miguel, Jesfa e Joú, foram descendentes de Baria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 17, 'Zabadia, Mosolão, Hezeci, Heber,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 18, 'Jesamarl, Jezlia, Jobab, foram filhos de Elfaal,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 19, 'Jacim, Zecri, Zabdi,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 20, 'Elioenai, Seletai, Eliel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 21, 'Adala, Baraia, Samarat, foram filhos de Semei,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 22, 'Jesfão, Heber, Eliel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 23, 'Abdon, Zecri, Hanan,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 24, 'Hanania, Elão, e Anatotia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 25, 'Jefdaia, Fanuel, foram filhos de Sesac.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 26, 'Samsari, Sooria, Otolia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 27, 'Jersia, Elia e Zecri, foram filhos de Jeroão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 28, 'Estes são os patriarcas e os chefes das famílias que habitaram em Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 29, 'Em Gabaon, porém, habitaram o pai de Gabaon e sua mulher, chamada Maaca,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 30, 'e seu filho primogénito Abdon, e Sur, Cis, Baal, Nadab,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 31, 'Gedor, Aio, Zaquer e Macelot.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 32, 'Macelot gerou Samaa. Estes habitaram em frente de seus irmãos em Jerusalém juntamente com seus irmãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 33, 'Ner gerou Cis, Cis gerou Saul, Saul gerou Jonatas, Melquisua, Abinadab e Esbaal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 34, 'O filho de Jónatas foi Meribaal; Meribaal gerou Mica.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 35, 'Filhos de Mica: Fiton, Meleque, Taraa e Acaz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 36, 'Acaz gerou Joada; Joada gerou Almat, Azmot e Zamri; Zamri gerou Mosa;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 37, 'Mosa gerou Banaa, cujo filho foi Rafa, do qual nasceu Elasa, que gerou Asel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 38, 'Asel teve seis filhos com estes nomes: Ezricão, Bocru, Ismael, Saria, Obdia e Hanan; todos estes foram filhos de Asel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 39, 'Os filhos de Esec, seu irmão, foram: Ulão primogênito, Jeús o segundo, e Elifalet o terceiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 40, 'Os filhos de Ulão foram homens robustíssimos e hábeis no atirar do arco; tiveram muitos filhos e netos, cento e cinquenta. Todos estes foram descendentes de Benjamim.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 1, 'Foi, assim, contado todo o Israel, e o seu número foi escrito no livro dos reis de Israel e de Judá. Depois Judá foi transportado a Babilônia, por causa dos seus pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 2, 'Os que primeiro se estabeleceram nas suas possessões e nas suas cidades, foram: os Israelitas, os sacerdotes, os Levitas e os Natineus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 3, 'Estabeleceram-se em Jerusalém parte dos filhos de Judá e de Benjamim, bem como de Efraim e de Manassés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 4, '(Da tribo de Judá) Otei, filho de Amiud, filho de Amri, filho de Omrai, filho de Boni, um dos filhos de Fares, filho de Judá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 5, 'De Siloni: Asaia, filho primogênito, e os seus filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 6, 'Dos filhos de Zara: Jeuel e os seus irmãos, em número de seiscentos e noventa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 7, 'Da tribo de Benjamim: Salo, filho de Mosolão, filho de Oduia, filho de Asana;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 8, 'Jobania, filho de Jeroboão; Ela, filho de Ozi, filho de Mocori; Mosolão, filho de Safatias, filho de Rauel, filho de Jebanias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 9, 'e os irmãos destes, por suas famílias, em número de novecentos e cinquenta e seis. Todos estes foram chefes de famílias, segundo as suas casas patriarcais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 10, 'Dos sacerdotes: Jedaia, Joiarib, Jaquim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 11, 'Azarias, filho de Helcias, filho de Mosolão, filho de Sadoc, filho de Maraiot, filho de Aquitob, pontífice da casa do Senhor;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 12, 'Adaias, filho de Jeroão, filho de Fassur, filho de Melquias; Maasai, filho de Adiei, filho de Jezra, filho de Mosolão, filho de Mosolamit, filho de Emer;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 13, 'e os irmãos destes, chefes de suas famílias, em número de mil setecentos e sessenta, homens fortíssimos em robustez para suportarem as fadigas do ministério da casa do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 14, 'Dos Levitas foram (estabelecer-se em Jerusalém): Semeia, filho de Hassub, filho de Ezricão, filho de Hasebia, um dos filhos de Merari;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 15, 'Bacbacar carpinteiro, Galal, Matanias, filho de Mica, filho de Zecri, filho de Asaf:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 16, 'Obdias, filho de Semeias, filho de Galai, filho de Iditun; Baraquias, filho de Asa, filho de Elcana, que morou nos arrabaldes de Netofatianos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 17, 'Os (chefes dos) porteiros foram: Seium, Acub, Telmon, Aimão e seus irmãos. Seium (era) o principal,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 18, 'e ainda hoje é o guarda da porta do rei, a oriente. Aí estão os porteiros do acampamento dos filhos de Levi.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 19, 'Seium, filho de Coré, filho de Abiasaf, filho de Coré, (estava ali) com seus irmãos e a casa de seu pai, isto é, os Coritas, que têm a superintendência das obras do ministério e guardam as portas do tabernáculo: os seus pais tinham tido a guarda da entrada do arraial do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 20, 'Fineias, filho de Eleázaro, era o seu chefe diante do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 21, 'Zacarias, filho de Mosolamia, era o porteiro da porta do tabernáculo da reunião.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 22, 'Todos estes escolhidos, para guardar as portas, eram em número de duzentos e doze e estavam incluídos no censo das suas cidades; foram estabelecidos por Davide e Samuel, o Vidente, por causa da sua fidelidade,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 23, 'tanto estes, como os seus filhos, para guardarem por turno as portas da casa do Senhor e as do tabernáculo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 24, 'Os (chefes dos) porteiros estavam alojados nos lugares correspondentes aos quatro ventos, isto é, ao oriente, ao ocidente, ao norte e ao meio-dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 25, 'Seus irmãos (os outros porteiros) moravam nas suas aldeias, e vinha cada um no seu sábado, de um tempo até outro tempo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 26, 'A estes quatro Levitas estava confiado todo o número dos porteiros, e eram os encarregados das câmaras e dos tesouros da casa do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 27, 'A sua habitação era à roda do templo do Senhor, durante a sua guarda; chegada a hora, abriam as portas pela manhã.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 28, 'Da linhagem destes eram também os que tinham a seu cuidado os vasos que serviam no ministério, porque os vasos entravam e saíam por conta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 29, 'Destes eram também os que tinham a seu cargo os utensílios do santuário, e que tinham cuidado da farinha, do vinho, do azeite, do incenso e dos aromas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 30, 'Eram os filhos dos Sacerdotes que compunham os perfumes com os aromas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 31, 'O levita Matatias, filho primogénito de Selum, Corita, tinha a seu cuidado tudo o que se frigia na sertã.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 32, 'Alguns dos filhos de Caat, seus irmãos, tinham a seu cargo os pães da proposição, para os prepararem sempre frescos em todos os sábados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 33, 'Estes eram os chefes dos cantores entre as famílias dos Levitas, que moravam nas pousadas do templo, para de contínuo, de dia e de noite, exercerem o seu ministério.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 34, 'Os chefes dos Levitas, príncipes das suas famílias, habitaram (sempre) em Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 35, 'Em Gabaon habitaram Jeiel, pai dos Gabaonitas, e sua mulher, que se chamava Maaca;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 36, 'Abdon, seu filho primogênito, e Sur, Cis, Baal, Ner, Nadab,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 37, 'Gedor, Aio, Zacarias e Macelot.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 38, 'Macelot gerou Samaan. Estes habitaram em Jerusalém com os seus irmãos, defronte dos (outros) seus irmãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 39, 'Ner gerou Cis; Cis gerou Saul; Saul gerou Jónatas. Melquisua, Abinadab e Esbaal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 40, 'Jónatas teve por filho a Meribaal; Meribaal gerou Mica.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 41, 'Os filhos de Mica foram: Fiton, Melec, e Taran, e Aaz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 42, 'Aaz gerou Jara, Jara gerou Alamat, Azmot e Zamri; Zamri gerou Mosa;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 43, 'Mosa gerou Banaa, cujo filho, Bafaia, gerou Elasa, do qual nasceu Asel;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 44, 'Asel teve seis filhos com estes nomes: Ezricão, Bocru, Ismael, Saria, Obdia, Hanan. Estes são os filhos de Asel.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 1, 'Os Filisteus combatiam contra Israel, e os Israelitas fugiram diante dos Filisteus, caindo (muitos deles) mortos no monte de Gelboé.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 2, 'Avançando os Filisteus no alcance de Saul e de seus filhos, mataram Jónatas, Abinadab e Melquisua, filhos de Saul.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 3, 'O combate tornou-se mais violento contra Saul; os frecheiros reconheceram-no e traspassaram-no com as suas setas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 4, 'Saul disse ao seu escudeiro: Desembaínha a tua espada e mata-me, não suceda virem estes incircuncidados zombar de mim. Todavia o escudeiro, possuído de temor, não quis fazer tal; então Saul pegou na sua espada e lançou-se sobre ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 5, 'Vendo isto o seu escudeiro, vendo que Saul certamente estava morto, ele mesmo se lançou também sobre a sua própria espada, e morreu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 6, 'Morreu Saul e três filhos seus, e toda a sua família pereceu juntamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 7, 'Os Israelitas que habitavam nos campos, ao verem que os homens de Israel fugiram e que estavam mortos Saul e seus filhos, abandonaram as suas cidades, e espalharam-se cada um para seu lado. Vieram (então) os Filisteus e estabeleceram-se nelas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 8, 'No dia seguinte, tirando os Filisteus os despojos dos mortos, encontraram Saul e os seus filhos estendidos no monte de Gelboé.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 9, 'Tendo-o despojado e cortado a cabeça e tirado as armas, levaram-no para a sua terra, para ser visto por todas as partes, e para que fosse exposto nos templos dos seus ídolos e aos olhos do povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 10, 'Consagraram as suas armas no templo do seu deus e pregaram a cabeça no templo de Dagon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 11, 'Tendo os habitantes de Jabes de Galaad ouvido tudo o que os Filisteus tinham feito a Saul,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 12, 'juntaram-se os mais fortes deles, partiram e tiraram os cadáveres de Saul e dos seus filhos, trouxeram-nos para Jabes, e enterraram os seus ossos debaixo do carvalho que havia em Jabes, e jejuaram sete dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 13, 'Morreu Saul por causa das suas iniquidades, por ter desobedecido ao mandamento que o Senhor lhe tinha imposto, e consultado os evocadores dos mortos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 14, 'Não consultou o Senhor, por isso ele o matou, e transferiu o seu reino para Davide, filho de Isaí.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 26, 'Os mais valentes do exército eram: Asael irmão de Joab, Alcanan de Belém, filho de Dodo.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 1, 'Congregou-se todo o Israel com Davide em Hebron, dizendo: Nós somos teus ossos e tua carne.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 2, 'Já antes, quando ainda reinava Saul, eras tu que conduzias Israel, porque a ti disse o Senhor teu Deus: Tu apascentarás o meu povo de Israel, tu serás o seu príncipe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 3, 'Todos os anciães de Israel foram, pois, ter com o rei a Hebron. Davide fez aliança com eles diante do Senhor, e eles ungiram-no rei sobre Israel, em conformidade com a palavra que o Senhor tinha proferido por meio de Samuel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 4, 'Davide marchou com todo o Israel sobre Jerusalém, que é Jebus, onde estavam os Jebuseus, habitantes do país.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 5, 'Os que habitavam em Jebus disseram a Davide: Tu não entrarás aqui. Contudo Davide tomou a fortaleza de Sião, que é a cidade de Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 6, 'Davide disse: Aquele que primeiro ferir um Jebuseu será príncipe e chefe. O primeiro a subir foi Joab, filho de Sarvia, que, (por isso) foi feito chefe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 7, 'Davide habitou na fortaleza, que, por tal motivo, se chamou cidade de Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 8, 'Edificou a cidade ao redor, desde Melo até à outra extremidade: Joab reparou o resto da cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 9, 'Davide fazia progressos, adiantando-se e fortalecendo-se, e o Senhor dos exércitos era com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 10, 'São estes os principais entre os homens fortes de Davide, que o ajudaram no seu reinado sobre todo de o Israel, segundo a palavra que o Senhor tinha dito a Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 11, 'Este é o número dos valentes de Davide: Jesbaão, filho de Hacamoni, chefe dos trinta. Este levantou a sua lança sobre trezentos, que feriu duma só vez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 12, 'Depois deste, Eleazar Aoíta, filho de Dodo, era um dos três valentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 13, 'Este achou-se com Davide em Fesdomim, quando os Filisteus se juntaram ali para dar batalha. Os campos daquela região estavam cheios de cevada, e o povo tinha fugido diante dos Filisteus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 14, 'mas estes (Eleazar e Sema) conservaram-se firmes no meio do campo e defenderam-no; tendo destroçado os Filisteus, deu o Senhor uma grande vitória ao seu povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 15, 'Três dos trinta príncipes desceram à rocha, onde estava Davide, junto da caverna de Odolão quando os Filisteus tinham acampado no vale de Refain.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 16, 'Davide estava na fortaleza, e uma guarnição de Filisteus estava em Belém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 17, 'Davide teve então um desejo e disse: Oh! quem me dera água da cisterna de Belém, que está junto da porta (da cidade)!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 18, 'Imediatamente estes três homens atravessaram pelo meio do acampamento dos Filisteus, tiraram água da cisterna de Belém, que estava junto da porta, e levaram-na a Davide, para que bebesse; ele não a quis beber, mas antes a ofereceu em libação ao Senhor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 19, 'dizendo: Longe de mim que eu tal faça na presença do meu Deus, que beba o sangue destes homens! De facto trouxeram-me água com perigo das suas vidas. Por esta causa, não a quis beber. Isto fizeram aqueles três valentíssimos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 20, 'Abisai, irmão de Joab, era o primeiro dos outros três. Também ele levantou a sua lança contra trezentos, que matou, e era o mais famoso entre os três.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 21, 'Era o mais notável dentre os três do segundo terno, e seu chefe, todavia nunca igualou os três primeiros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 22, 'Banaias, (natural) de Cabseel, filho de Jojada, homem valentíssimo que se assinalou em grandes feitos, matou os dois Arieis (ou grandes leões) de Moab. (Um dia) desceu e matou um leão no meio duma cisterna em tempo de neve.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 23, 'Matou também um Egípcio, cuja estatura era de cinco côvados, e tinha uma lança como o órgão do tear dos tecelões. Foi contra ele com um pau, tirou-lhe a lança que tinha na mão, e com esta mesma lança o matou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 24, 'Estas coisas fez Banalaa, filho de Jojada, que era o mais afamado entre os três valentes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 25, 'o principal entre os trinta; todavia não igualava os três primeiros. Davide o admitiu para seu conselheiro íntimo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 27, 'Samot de Arori, Heles de Falon,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 28, 'Ira de Técua, filho de Aces, Abiezer de Anatot,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 29, 'Sobocai de Husat, Ilai de Aó,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 30, 'Maarai de Netofat, Heled, filho de Baana de Netofat,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 31, 'Etai, filho de Ribai de Gabaa da tribo de Benjamim, Banaia de Faraton,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 32, 'Hurai da torrente de Gaas, Abiel de Harbat, Azmot de Baurami, Eliab de Salaboni;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 33, 'Bené-Assen Gezonita, Jonatan filho de Sage de Arari,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 34, 'Aião filho de Sacar de Axari,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 35, 'Elifal filho de Ur,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 36, 'Efer de Mecerat, Aia de Felon,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 37, 'Hesro do Carmelo. Naarai, filho de Asbal,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 38, 'Joel, irmão de Natan, Mibaar, filho de Agaral,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 39, 'Selec de Amoni, Naarai de Berot, escudeiro de Joab, filho de Sarvia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 40, 'Ira de Jeter, Gareb de Jeter,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 41, 'Urias Heteu, Zabad filho de Ooli,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 42, 'Adina filho de Siza da tribo de Ruben, chefe dos Rubenitas, e com ele outros trinta;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 43, 'Hanan, filho de Maca, Josafat Matani,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 44, 'Ozias Astarotita, Sama e Jeiel, filhos de Hotão de Arori,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 45, 'Jediel, filho de Samri, Joa, seu irmão, de Tosa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 46, 'Eliel de Maumi, Jeribal e Josaia, filhos de Elnaem, Jetma de Moab, Eliel, Obed e Jeslel de Masobia.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 1, 'Estes são os que foram juntar-se com Davide em Siceleg, quando ainda fugia de Saul, filho de Cis; homens fortíssimos e excelentes guerreiros,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 2, 'que manejavam o arco, hábeis em arremessar com ambas as mãos pedras com fundas e em atirar setas; eram parentes de Saul, da tribo de Benjamim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 3, 'O principal era Aiezer, depois Joás, (ambos) filhos de Sarna, de Gabaa, Jaziel e Falet, filhos de Azmot, Baraca, Jeú de Anatot,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 4, 'Samaias de Gabaon, o mais valente dos trinta e comandante dos trinta. Jeremias, Jeeziel, Joanan, Jezabad de Gedera,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 5, 'Elusai, Jerimut, Baalia, Samaria, Safatia de Haruf,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 6, 'Elcana, Jesia, Azareel, Joezer, Jesbaão de Carelm,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 7, 'e Joela e Zabadia, filhos de Jeroão de Gedor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 8, 'Além destes, de entre os Gaditas passaram-se para Davide, quando estava oculto no deserto, homens muito valentes, soldados óptimos, armados de escudo e lança; o seu aspecto era como de leões, e a sua agilidade como das gazelas das montanhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 9, 'O primeiro era Ezer, o segundo Obdias, o terceiro Eliab,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 10, 'o quarto Masmana, o quinto Jeremias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 11, 'o sexto foi Eti, o sétimo Eliel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 12, 'o oitavo Joanan, o nono Elzebad,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 13, 'o décimo Jeremias, o undécimo Macbanai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 14, 'Estes eram da tribo de Gad, chefes do exército. O menor era capaz de atacar sòzinho cem soldados, e o maior mil.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 15, 'Foram estes que passaram o Jordão no primeiro mês, quando ele costumava trasbordar por cima das de suas ribeiras, e puseram em fuga todos os que habitavam nos vales, assim ao oriente, como ao ocidente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 16, 'Foram também vários da tribo de Benjamim e da tribo de Judá, à fortaleza em que estava Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 17, 'Davide saiu-lhes ao encontro e disse: Se vindes pacificamente a socorrer-me, o meu coração se unirá ao vosso; mas se me armais ciladas, secundando os meus inimigos, embora eu tenha as minhas mãos limpas de qualquer iniquidade, o Deus de nossos pais seja disto testemunha e juiz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 18, 'Amasai, porém, o primeiro entre os trinta, revestido do espírito (divino), disse: Nós somos teus, ó Davide, e estamos contigo, ó filho de Isaí. A paz, a paz seja contigo, a paz seja com teus defensores, porque o teu Deus te protege. Davide recebeu-os e constituiu-os com andantes das tropas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 19, 'Também alguns da tribo de Manassés se passaram para Davide, quando ele marchava com os Filisteus contra Saul, para pelejar. Todavia não socorreram os Filisteus, porque os príncipes dos Filisteus, tendo feito conselho, despediram Davide, dizendo: Ele, com perigo das nossas vidas, voltará para Saul, seu amo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 20, 'Quando ele voltou para Siceleg, fugiram para ele, da tribo de Manassés, Ednas, Jozabad, Jediel, Miguel, Jozabad, Eliu e Salati, com andantes de mil homens na tribo de Manassés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 21, 'Estes prestaram auxílio a Davide contra os guerrilheiros (dos Amalecitas), porque todos eram homens fortíssimos, e foram feitos capitães do exército.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 22, 'Assim cada dia concorria gente a Davide para o auxiliar, até que se fez um grande número, como um exército de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 23, 'Eis o número dos homens equipados que foram ter com Davide, quando estava em Hebron, a fim de transferirem para ele o reino de Saul, conforme a palavro do Senhor:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 24, 'Dos filhos de Judá, que manejavam escudo e lança, seis mil e oitocentos homens, prontos para a peleja;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 25, 'dos filhos de Simeão, homens fortíssimos para a guerra, sete mil e cem;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 26, 'dos filhos de Levi, quatro mil e seiscentos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 27, 'e Jojada, príncipe da linhagem de Aarão, com três mil e setecentos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 28, 'e Sadoc, jovem de excelente índole, e a casa de seu pai, com vinte e dois chefes;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 29, 'dos filhos de Benjamim, irmãos de Saul, três mil, porque uma grande parte destes seguia ainda a casa de Saul;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 30, 'dos filhos de Efraim, vinte mil e oitocentos homens muito esforçados e de grande reputação nas suas famílias;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 31, 'da meia tribo de Manassés, dezoito mil, que foram, nominalmente, designados, para eleger rei a Davide;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 32, 'dos filhos de Issacar, homens inteligentes, que sabiam notar todos os tempos para ordenarem o que Israel devia fazer, duzentos chefes e todos os seus irmãos, sob as suas ordens;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 33, 'dos de Zabulon, que iam à guerra e que se punham em campo providos de armas guerreiras, foram em auxílio cinquenta mil, com um coração sincero;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 34, 'dos de Neftali, mil oficiais e, com eles, trinta e sete mil homens, armados de escudos e de lanças;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 35, 'dos de Dan, vinte e oito mil e seiscentos, prontos para a guerra;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 36, 'dos de Aser, quarenta mil, homens de guerra, aparelhados para o combate.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 37, 'Da banda de além do Jordão, cento e vinte mil, dos filhos de Ruben, de Gad e da meia tribo de Manassés, providos de armas de guerra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 38, 'Todos estes homens guerreiros, prontos para combater, foram com um coração sincero a Hebron, para constituir Davide sobre todo o Israel. Também todo o resto de Israel tinha um mesmo coração para que Davide fosse feito rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 39, 'Demoraram-se lá, junto a Davide, três dias, comendo e bebendo, porque seus irmãos lhes tinham preparado provisões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 40, 'Mesmo os que habitavam perto, até os de Issacar, de Zabulon e de Neftali, traziam em jumentos, camelos, machos e bois, víveres: farinha, figos, passas de uva, vinho, azeite, bois e carneiros em grande abundância, porque havia regozijo em Israel.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 1, 'Davide teve conselho com os chefes de milhar, com os centuriões e com todos os príncipes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 2, 'e a todo o ajuntamento de Israel: Se vos parece bem e se o que vos vou propor vem do Senhor nosso Deus, mandemos chamar todos os outros nossos irmãos, por todas as províncias de Israel, bem como os sacerdotes e Levitas, que habitam nos arrabaldes das cidades, para que se reunam junto de nós,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 3, 'e reconduzamos para nós a arca do nosso Deus, já que a não buscamos no tempo de Saul.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 4, 'Todo o ajuntamento respondeu que assim se fizesse, porque a todo o povo agradara a proposta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 5, 'Reuniu, pois, Davide todo o Israel desde o rio Sior do Egito até à entrada de Emat, para conduzir a arca de Deus de Cariatiarim (a Jerusalém).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 6, 'Davide saiu com todos os homens de Israel para a colina de Cariatiarim, que está na tribo de Judá, para de lá trazer a arca do Senhor Deus, que está sentado sobre os querubins, diante da qual é invocado o seu nome.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 7, 'E puseram a arca de Deus em cima dum carro novo, retirando-a da casa de Abinadab; Oza e seu irmão guiavam o carro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 8, 'Entretanto Davide e todo o Israel manifestavam a sua alegria diante de Deus com toda a sua força em cânticos, tangendo cítaras, saltérios, tambores, timbales e trombetas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 9, 'Quando chegaram à eira de Quidon, Oza estendeu a mão para suster a arca, porque um boi, recalcitrando, a tinha feito inclinar um pouco.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 10, 'Irritou-se o Senhor contra Oza e feriu-o por ter tocado a arca (não sendo sacerdote); Oza morreu ali diante do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 11, 'Davide afligiu-se, porque o Senhor tinha ferido Oza com tal castigo, e chamou àquele lugar a Divisão de Oza, (nome que conserva) até ao dia de hoje.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 12, 'Davide temeu então a Deus, dizendo: Como poderei eu levar para minha casa a arca de Deus?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 13, 'Por esta razão não a conduziu para a sua casa, isto é, para a cidade de Davide, mas mandou-a levar para casa de Obededom de Get.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 14, 'Ficou, pois, a arca de Deus em casa de Obededom durante três meses; e o Senhor abençoou a sua casa e tudo o que Ihe pertencia.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 1, 'Hirão, rei de Tiro, enviou também mensageiros a Davide, madeiras de cedro, pedreiros e carpinteiros, para lhe fazerem uma casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 2, 'Davide reconheceu que o Senhor o tinha confirmado rei sobre Israel e que o seu reino se tinha elevado por amor de Israel, seu povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 3, 'Davide tomou também em Jerusalém outras mulheres, e teve filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 4, 'Estes são os nomes dos que lhe nasceram em Jerusalém: Samua, Sobad, Natan, Salomão,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 5, 'Jebaar, Elisua, Elifalet,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 6, 'Noga, Nafeg, Jafia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 7, 'Elisama, Baaliada e Elifalet.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 8, 'Os Filisteus, tendo ouvido dizer que Davide tinha sido ungido rei sobre todo o Israel, juntaram-se todos para o atacarem. Davide, tendo sabido isto, foi ao seu encontro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 9, 'Os Filisteus, tendo chegado, espalharam-se pelo vale de Refaim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 10, 'Davide consultou o Senhor, dizendo: Irei eu contra os Filisteus, e entregar-mos-ás tu nas minhas mãos? O Senhor respondeu-lhe: Vai, que eu tos entregarei nas tuas mãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 11, 'Tendo eles, pois, chegado a Baalfarasim, Davide desbaratou-os aí e disse: O Senhor dividiu, por meio da minha mão, os meus inimigos, assim como se dividem as águas; por isso este lugar se chamou Baalfarasim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 12, 'Os Filisteus deixaram ali os seus deuses, que Davide mandou queimar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 13, 'Os Filisteus fizeram ainda outra invasão e espalharam-se pelo vale.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 14, 'Davide consultou segunda vez a Deus, e Deus disse-lhe: Não vás atrás deles, e irás contra eles do lado dos balsameiros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 15, 'E, quando ouvires um rumor como de passos, entre as copas dos balsameiros, então sairás à peleja; porque Deus saiu diante de ti, para desbaratar o acampamento dos Filisteus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 16, 'Fez, pois, Davide como o Senhor lhe tinha mandado, e desbaratou o acampamento dos Filisteus, desde Gabaon até Gazer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 17, 'A fama de Davide espalhou-se por todos os povos, e o Senhor o fez formidável a todas as gentes.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 1, 'Edificou também casa para si, na cidade de Davide, e edificou um lugar (próprio) para a arca de Deus e levantou-lhe um tabernáculo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 2, 'Então disse Davide: Não é permitido que a arca de Deus seja levada por alguém senão pelos Levitas, aos quais o Senhor escolheu para a levarem e para serem seus ministros perpètuamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 3, 'Congregou, pois, todo o Israel em Jerusalém, para trasladar a arca de Deus ao lugar, que lhe tinha preparado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 4, 'Convocou também os filhos de Aarão e os Levitas:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 5, 'dos filhos de Caat, Uriel, que era o chefe, com seus irmãos em número de cento e vinte;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 6, 'dos filhos de Merari, o principal, que era Asaia, com seus irmãos em número de duzentos e vinte;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 7, 'dos filhos de Gerson, o principal que era Joel, com seus irmãos em número de cento e trinta;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 8, 'dos filhos de Elisafan, o principal, que era Semeias, com seus irmãos em número de duzentos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 9, 'dos filhos de Hebron, o principal, que era Eliel, com seus irmãos em número de oitenta;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 10, 'dos filhos de Oziel, o principal, que era Aminadab, com seus irmãos em número de cento e doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 11, 'Davide chamou os sacerdotes Sadoc e Ablatar, os Levitas Uriel, Asala, Joel, Semeias, Eliel e Aminadab,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 12, 'e disse-lhes: Vós, que sois os chefes das famílias levíticas, purificai-vos com vossos irmãos e transportai a arca do Senhor Deus de Israel ao lugar que lhe foi preparado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 13, 'Com efeito, da primeira vez, porque não estáveis presentes, nos feriu o Senhor, porque não fomos buscar (a arca) segundo as determinações da lei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 14, 'Os sacerdotes, pois, e os Levitas purificaram-se, para transportar a arca do Senhor Deus de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 15, 'Os filhos de Levi tomaram a arca de Deus aos ombros pelos varais, como Moisés tinha ordenado conforme a palavra do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 16, 'Davide disse aos chefes dos Levitas que constituíssem dentre seus irmãos cantores com instrumentos músicos, isto é, com cítaras, harpas e címbalos, a fim de que ressoasse até ao céu o som da alegria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 17, 'Constituíram, pois, dos Levitas: Heman, filho de Joel, e, dentre os seus irmãos, Asaf, filho de Baraquias; dos filhos de Merari, seus irmãos, (constituíram) Etan, filho de Cusala;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 18, 'com eles, os seus irmãos de segunda ordem (ou coro) Zacarias, Ben, Jazlel, Semlramot, Jaiel, Ani, Eliab, Banalas, Maasias, Matatias, Elifalu, Macenias, Obededom e Jeiel, que eram porteiros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 19, 'Os cantores Heman, Asaf e Etan tocavam címbalos de bronze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 20, 'Zacarias, Oziel, Semlramot, Jaiel, Ani, Eliab, Maasias e Banaias, cantavam, ao som de cítaras, hinos misteriosos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 21, 'Matatias, Ellfalu, Macenias, Obededom, Jeiel e Ozazlu cantavam, ao som das harpas na oitava (inferior), cânticos triunfais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 22, 'Conenias, chefe dos Levitas, presidia ao canto para dar o tom, porque era muito entendido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 23, 'Baraquias e Elcana eram porteiros da arca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 24, 'Os sacerdotes Sebenlas, Josafat, Natanael, Amasai, Zacarias, Banaias e Eliezer, tocavam trombetas diante da arca de Deus. Obededom e Jeías eram (também) porteiros da arca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 25, 'Davide, todos os anciães de Israel e os chefes de milhar, foram com alegria para trasladarem da casa de Obededom (para Jerusalém) a arca da aliança do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 26, 'Tendo Deus assistido aos Levitas, que levavam a arca da aliança do Senhor, foram imolados sete touros e sete carneiros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 27, 'Davide estava vestido duma túnica de linho fino, e, da mesma forma, todos os Levitas que levavam a arca, e os cantores e Conénias, regente do coro dos cantores. Davide estava também vestido dum éfode de linho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 28, 'Todo o Israel acompanhava a arca da aliança do Senhor, com vozes de júbilo, ao som de clarins, trombetas, címbalos, harpas e cítaras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 29, 'Quando a arca da aliança do Senhor chegou à cidade de Davide, Micol, filha de Saul, olhando da janela, viu que o rei Davide saltava e dançava (diante da arca) e desprezou-o no seu coração.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 1, 'Levaram a arca de Deus e colocaram-na no meio do tabernáculo, que Davide lhe tinha levantado, e ofereceram holocaustos e hóstias pacíficas diante de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 2, 'Tendo Davide acabado de oferecer os holocaustos e as hóstias pacíficas, abençoou o povo em nome do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 3, 'Distribuiu a todos um por um, tanto a homens como a mulheres, uma torta de pão, um pedaço de carne de vaca assada e flor de farinha frita em azeite.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 4, 'Estabeleceu dentre os Levitas os que haviam de servir diante da arca do Senhor, fazer comemoração das suas obras, glorificar e louvar o Senhor Deus de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 5, 'Nomeou Azaf chefe, Zacarias o segundo, e depois Jaiel, Semiramot, Jeiel, Matatias, Eliab, Banaias e Obededom: Jeiel para tocar harpas e cítaras, Asaf para tocar os címbalos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 6, 'e os sacerdotes Banaias e Jazlel para tocarem continuamente a trombeta diante da arca da aliança do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 7, 'Naquele dia Davide constituiu Asaf primeiro cantor, para cantar os louvores ao Senhor com seus irmãos, (dizendo):'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 8, 'Louvai o Senhor, e invocai o seu nome: tornai conhecidas as suas obras entre os povos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 9, 'Cantai em seu louvor, salmodiai para sua glória, anunciai todas as suas maravilhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 10, 'Louvai o seu santo nome; alegre-se o coração dos que buscam o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 11, 'Buscai o Senhor e a sua fortaleza; buscai sempre a sua face.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 12, 'Lembrai-vos das maravilhas que ele fez, dos seus prodígios e dos juízos da sua boca,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 13, 'vós que sois os descendentes de Israel, seu servo, filhos de Jacob, seu escolhido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 14, 'Ele é o Senhor nosso Deus; em toda a terra se exercem os seus juízos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 15, 'Lembrai-vos eternamente do seu pacto, da palavra que disse para mil gerações (isto é, para sempre),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 16, '(do pacto) que fez com Abraão, do seu juramento a Isaac,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 17, 'do que firmemente estabeleceu com Jacob, e com Israel como pacto eterno,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 18, 'dizendo: Eu hei-de dar-te a terra de Canaan, como parte da vossa herança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 19, 'Quando eles eram em pequeno número, pobres e estrangeiros nela,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 20, 'quando passavam de nação em nação, dum reino para outro povo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 21, 'não permitiu que alguém lhes fizesse mal, antes por causa deles castigou reis:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 22, 'Não toqueis (disse) os meus ungidos, não façais mal aos meus profetas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 23, 'Cantai ao Senhor, (ó habitantes) de toda a terra; anunciai de dia em dia a salvação que vos deu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 24, 'Publicai a sua glória entre as gentes, e as suas maravilhas entre todos os povos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 25, 'porque o Senhor é grande e digno de todo o louvor, é mais terrível que todos os deuses,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 26, 'pois todos os deuses das gentes são ídolos. O Senhor (é o que) fez os céus;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 27, 'a majestade e o esplendor estão diante dele, a fortaleza e a alegria na sua morada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 28, 'Tributai ao Senhor, ó famílias dos povos, tributai ao Senhor glória e poder,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 29, 'tributai ao Senhor a glória devida ao seu nome; trazei ofertas e vinde à sua presença, adorai o Senhor com os santos ornamentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 30, 'Trema a terra diante da sua face, porque ele deu fundamentos estáveis ao universo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 31, 'Alegrem-se os céus, e exulte a terra! Diga-se entre as nações: O Senhor é o rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 32, 'Brama o mar e tudo o que nele se contêm; exultem os campos e tudo o que há neles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 33, 'Que as árvores do bosque soltem gritos de alegria diante do Senhor, porque ele vem julgar a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 34, 'Dai glória ao Senhor, porque é bom, porque a sua misericórdia é eterna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 35, 'Dizei: Salva-nos, ó Deus nosso Salvador, junta-nos e tira-nos do meio das gentes, para que celebremos o teu santo nome, e ponhamos a nossa glória em te louvar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 36, 'Bem-dito seja o Senhor Deus de Israel, de eternidade em eternidade. Todo o povo diga: "Amen!" e: "Louvai o Senhor".'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 37, 'Davide deixou ali, diante da arca da aliança do Senhor, Asaf e os seus irmãos, para servirem continuamente na presença da arca, todos os dias, e por seus turnos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 38, 'Deixou também Obededom e os seus irmãos, que eram sessenta e oito, e estabeleceu como porteiros a Obededom, filho de Iditun, e a Hosa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 39, 'Pôs o sacerdote Sadoc e os seus irmãos sacerdotes diante do tabernáculo do Senhor no lugar alto, que havia em Gabon,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 40, 'para oferecerem continuamente holocaustos ao Senhor, de manhã e de tarde, em cima do altar dos holocaustos, conforme tudo o que está escrito na lei do Senhor, prescrita a Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 41, 'Depois dele, estavam Heman, Iditun e os outros que tinham sido escolhidos e designados cada um por seu nome para louvar o Senhor, dizendo que a sua misericórdia é eterna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 42, 'Heman e Iditun tocavam também a trombeta, e os címbalos, e (tinham) instrumentos músicos para cantarem louvores a Deus. Destinou para porteiros os filhos de Iditun.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 43, 'E todo o povo voltou para sua casa, e também Davide para a sua, a fim de a abençoar.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 1, 'Habitando já Davide no seu palácio, disse ao profeta Natan: Eu habito numa casa de cedro, e a arca da aliança do Senhor está sob uma tenda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 2, 'Natan respondeu a Davide: Faze tudo o que tens no teu coração, porque Deus é contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 3, 'Porém, naquela noite, o Senhor falou a Natan, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 4, 'Vai, e dize a Davide, meu servo: Isto diz o Senhor: Tu não me edificarás uma casa para eu habitar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 5, 'Nunca habitei em casa desde o tempo em que libertei Israel (do Egito), até ao presente, mas tenho sempre andado, de lugar em lugar, debaixo duma tenda,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 6, 'morando com todo o Israel. Porventura dirigi eu alguma palavra a algum dos juízes de Israel, a quem tinha mandado que apascentassem o meu povo, dizendo-lhe: Por que não me edificais vós uma casa de cedro?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 7, 'Agora, pois, dirás assim ao meu servo Davide: Eis o que diz o Senhor dos exércitos: Quando tu conduzias os rebanhos a pastar, eu te escolhi para seres chefe do meu povo de Israel;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 8, 'fui contigo, por onde quer que andavas, e extingui, à tua vista, todos os teus inimigos e fiz o teu nome tão ilustre como o dum dos grandes da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 9, 'Dei um lugar fixo ao meu povo de Israel, no qual está confirmado, em que habita, e donde nunca mais será removido (se obedecer à minha lei); nem os filhos da iniquidade o oprimirão, como antes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 10, 'no tempo em que dei juízes ao meu povo de Israel. Humilhei todos os teus inimigos, e declaro-te que o Senhor há-de fundar para ti uma casa (estável).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 11, 'Quando os teus dias estiverem completos para ires para teus pais, eu suscitarei um do teu sangue, que será dos teus filhos, e estabelecerei o seu reino.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 12, 'Esse me edificará uma casa, e firmarei o seu trono para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 13, 'Eu serei seu pai, e ele será meu filho; não tirarei dele a minha misericórdia, como a tirei de (Saul) teu predecessor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 14, 'mas eu o estabelecerei na minha casa e no meu reino para sempre, e o seu trono será imóvel perpètuamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 15, 'Natan referiu a Davide todas estas palavras e toda esta visão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 16, 'Tendo ido o rei Davide diante do Senhor e tendo ali parado, disse: Quem sou eu, Senhor Deus, e que casa é a minha, para que me faças tais coisas?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 17, 'Mas isto pareceu ainda pouco em tua presença, e por isso falaste sobre a casa de teu servo, para o futuro, e me fizeste mais notável do que todos os homens, Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 18, 'Que mais pode desejar Davide, tendo tu glorificado assim o teu servo? Tu conheces, Senhor, o teu servo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 19, 'Senhor, por amor do teu servo, conforme o teu coração, procedeste com tanta magnificência, e quiseste que ele conhecesse todas estas maravilhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 20, 'Senhor, não há outro semelhante a ti, não há outro Deus senão tu, entre todos aqueles de quem temos ouvido falar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 21, 'Que outro povo há, pois, como o teu povo de Israel, nação única na terra, para a qual se encaminhou Deus, para a livrar, para a fazer o seu povo e para, pelo seu poder e pelos seus terrores, expulsar as nações de diante dela, a quem tinha livrado do Egito?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 22, 'Estabeleceste o teu povo de Israel por teu povo para sempre, e tu, ó Senhor, te constituiste o seu Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 23, 'Agora, Senhor, confirmei para sempre a promessa que fizeste a teu servo e à sua casa, e faze o que disseste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 24, 'Para sempre permaneça e seja glorificado o teu nome, e diga-se: O Senhor dos exércitos é o Deus de Israel, e a casa de Davide, seu servo, permanece sempre estável diante dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 25, 'Tu mesmo, Senhor meu Deus, revelaste ao ouvido do teu servo que lhe edificarias uma casa, e, por isso, o teu servo se encheu de confiança, para orar em tua presença.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 26, 'Agora, pois, ó Senhor, tu és Deus (infalível), e tu prometeste tão grandes benefícios ao teu servo!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 27, 'Abençoa, (então) a casa do teu servo, para que subsista sempre diante de ti, porque, abençoando-a tu, ó Senhor, para sempre será abençoada.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 1, 'Depois disto, aconteceu que Davide derrotou os Filisteus e os humilhou, arrebatando às suas mãos Get e as cidades da sua dependência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 2, 'Derrotou também Moab, e os Moabitas ficaram sujeitos a Davide, pagando-lhe tributos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 3, 'Neste tempo Davide derrotou também Adarezer, rei de Soba, no país de Hemat, quando partiu para estender o seu império até ao rio Eufrates.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 4, 'Davide tomou-lhe mil carros tirados a quatro cavalos e sete mil cavaleiros, e cortou os jarretes a todos os cavalos dos carros, excepto aos cavalos de cem carros, que reservou para si.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 5, 'Sobrevindo os Sírios de Damasco em socorro de Adarezer, rei de Soba, Davide matou-lhes vinte e dois mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 6, 'Pôs guarnição em Damasco, para que também tivesse sujeita a si a Síria e lhe fosse tributária. O Senhor ajudou-o em tudo aquilo que empreendeu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 7, 'Tomou também Davide os escudos de ouro, que tinham sido dos soldados de Aderezer, e levou-os para Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 8, 'Tomou também de Tebat e de Cun, cidades do rei Adarezer, grande quantidade de bronze, com o qual Salomão fez o mar de bronze, e as colunas e os utensílios de bronze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 9, 'Ora Tou, rei de Hemat, tendo ouvido dizer que Davide tinha desfeito todo o exército de Adarezer, rei de Soba,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 10, 'enviou Adorão, seu filho, ao rei Davide para lhe pedir a sua aliança e para lhe dar os parabéns, por ter desfeito e vencido Adarezer, porque Tou era inimigo de Adarezer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 11, 'Consagrou o rei Davide ao Senhor todos os vasos de ouro, de prata, e de bronze, (que Tou havia mandado) com a prata e ouro que tinha tomado a todos os povos, assim da Iduméa, de Moab e de Amon, como também dos Filisteus e dos Amalecitas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 12, 'Por outro lado Abisai, filho de Sarvia, derrotou dezoito mil Idumeus no vale das Salinas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 13, 'e pôs guarnições na Iduméa, para que a Iduméa ficasse sujeita a Davide. O Senhor salvou Davide em todas as expedições que fez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 14, 'Davide reinou sobre todo o Israel, e julgava e fazia justiça a todo o seu povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 15, 'Joab, filho de Sarvin, era chefe dos exércitos; Josafat, filho de Ailud, arquivista;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 16, 'Sadoc, filho de Aquitob, e Almelec, filho de Abiatar, eram sacerdotes; Susa era secretário;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 17, 'Banaias, filho de Jojada, comandava as legiões dos Cereteus e dos Feleteus; e os filhos de Davide eram os primeiros ao lado do rei.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 1, 'Depois disto, faleceu Naas, rei dos Amonitas, e seu filho reinou em seu lugar. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 2, 'Davide disse: Quero mostrar o meu afeto a Hanon, filho de Naas, pois que recebi favores de seu pai. E Davide mandou mensageiros para o consolarem na morte de seu pai. Quando eles chegaram ao pais dos Amonitas, para consolarem Hanon,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 3, 'os grandes dos Amonitas disseram a Hanon: Julgas talvez que Davide, por honrar a memória de teu pai, te mandou homens que te consolassem? Não vês que os servos vieram para explorar e examinar, e esquadrinhar o teu país?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 4, 'Hanon, então, mandou rapar a cabeça e a barba aos servos de Davide, fez-Ihes retalhar as suas túnicas da cintura até aos pés, e despediu-os.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 5, 'Tendo sido avisado disto, Davide mandou (alguns dos seus homens) ao encontro deles (porque era grande o ultraje que tinham padecido), para lhes dizerem que ficassem em Jericó, até lhes crescer a barba, e que então voltassem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 6, 'Vendo, os Amonitas, assim Hanon com o todo o povo, que tinham feito injúria a Davide, mandaram mil talentos de prata, para tomarem a seu soldo carros de guerra e cavalaria da Mesopotâmia, dos Sírios de Maaca e de Soba.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 7, 'Assoldaram trinta e dois mil carros e o rei Maaca com o seu povo, os quais acamparam defronte de Medaba. Os Amonitas, tendo-se juntado das suas cidades, saíram para a guerra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 8, 'Davide, informado disto, mandou Joab e todo o exército de homens valentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 9, 'Tendo saído os Amonitas, formaram-se em batalha junto da porta da cidade; e os Sírios os reis, que tinham ido em seu socorro, fizeram alto separadamente na campina.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 10, 'Joab, vendo que lhe queriam dar batalha pela frente e pela retaguarda, escolheu os homens mais esforçados de todo o Israel e marchou contra os Sírios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 11, 'Do resto do exército deu o comando a Abisai, seu irmão, para que enfrentasse os Amonitas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 12, 'Disse: Se os Sírios prevalecerem contra mim, tu virás socorrer-me; se os Amonitas prevalecerem contra ti, eu te socorrerei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 13, 'Esforça-te e pelejemos valorosamente pelo nosso povo e pelas cidades do nosso Deus; e o Senhor fará o que bem lhe parecer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 14, 'Marchou, pois, Joab e o povo que estava com ele à batalha contra os Sírios, e pô-los em fuga.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 15, 'Os Amonitas, vendo que os Sírios tinham fugido, fugiram eles também de Abisai, irmão de Joab, e entraram na cidade. Joab voltou para Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 16, 'Os Sírios, vendo-se vencidos por Israel, mandaram mensageiros e fizeram vir os Sírios que viviam da banda de além do rio (Eufrates). Sofac, general do exército de Adarezer, era o seu comandante.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 17, 'Davide, avisado disto, juntou todo o Israel, passou o Jordão, deu de repente sobre eles e acometeu-os pela frente com o seu exército formado em batalha, resistindo eles por seu lado (com valor).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 18, 'Porém os Sírios fugiram diante de Israel, e Davide matou deles sete mil homens dos carros e quarenta mil de pé, assim como Sofac, general do exército.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 19, 'Vendo os servos de Adarezer que eram vencidos pelos Israelitas, passaram para Davide e ficaram-lhe sujeitos. E a Síria não quis mais dar socorro aos Amonitas.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 1, 'Ora aconteceu que, tendo decorrido um ano, no tempo em que os reis costumam ir para a guerra, Joab juntou o exército e a flor das tropas, assolou o pais dos Amonitas e pôs cerco a Raba. Davide, porém, ficou em Jerusalém, enquanto Joab bateu Jelaba e a destruiu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 2, 'Davide tirou a coroa de cima da cabeça de Melcom, e encontrou nela o peso dum talento de ouro e pedras preciosíssimas, de que fez para si um diadema; levou também muitos despojos da cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 3, 'Mandou sair o povo, que havia nela, e empregou-o em serrar, em afiar ferros, em serviços com machados. O mesmo fez em todas as cidades dos Amonitas. (Depois) voltou para Jerusalém com todo o seu povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 4, 'Depois disto, travou uma batalha em Gazer contra os Filisteus, durante a qual Sobocai de Husat matou Safai da raça dos Refaim. Os Filisteus ficaram humiIhados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 5, 'Houve ainda outra guerra contra os Filisteus, na qual Adeodato, filho de Salto de Belém, matou um irmão de Golias, de Get, que tinha uma lança cuja haste era como um órgão dos tecelões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 6, 'E ainda houve outra batalha em Get, onde foi encontrado um homem de grandíssima estatura, que tinha seis dedos nos pés e nas mãos, isto é, vinte e quatro ao todo, o qual descendia também da raça de Rafa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 7, 'Este insultava Israel, mas Jonatan, filho de Samaa, irmão de Davide, matou-o. Estes são os filhos de Rafa em Get, que foram mortos pelas mãos de Davide e das suas tropas.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 1, 'Levantou-se, pois, Satanás contra Israel, e incitou Davide a fazer o recenseamento de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 2, 'Davide disse a Joab e aos principais do povo: Ide, contai Israel desde Bersabé até Dan, e trazei-me o número, para eu o saber.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 3, 'Joab respondeu: O Senhor multiplique o seu povo cem vezes mais do que ele é. Porventura, ó rei, meu senhor, não são todos servos teus? Por que procura o meu senhor fazer uma coisa que será imputada como pecado a Israel?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 4, 'Contudo preveleceu a ordem do rei. Joab partiu, andou girando por todo o Israel e voltou para Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 5, 'Deu a Davide a lista daqueles que tinha recenseado: o número total de Israel era de um milhão e cem mil homens capazes de tomar armas; o de Judá era de quatrocentos e setenta mil homens de guerra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 6, 'Joab não contou os da tribo de Levi, nem os da tribo de Benjamim, porque lhe repugnava a ordem do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 7, 'Esta ordem desagradou a Deus, o qual feriu Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 8, 'Davide disse a Deus: Eu cometi um grande pecado em fazer isto, peço-te que perdoes a culpa ao teu servo, porque procedi nèsciamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 9, 'O Senhor falou a Gad, vidente de Davide, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 10, 'Vai, fala a Davide e dize-lhe: Eis o que diz o Senhor: Eu te dou três coisas à escolha; escolhe uma qual quiseres, e eu ta farei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 11, 'Tendo ido Gad à presença de Davide, disse-lhe: Eis o que diz o Senhor: Escolhe o que quiseres:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 12, 'ou sofrer a fome durante três anos, ou fugir diante dos teus inimigos durante três meses, sem poderes escapar da sua espada, ou estar debaixo da espada do Senhor durante três dias, grassando a peste pelo país, e fazendo estragos o anjo do Senhor em todas as terras de Israel. Vê, pois, agora que hei-de responder a quem me enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 13, 'Davide respondeu a Gad: De toda a parte me vejo em grandes angústias, mas para mim é melhor cair nas mãos do Senhor, porque é de muita misericórdia, do que cair nas mãos dos homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 14, 'Mandou, pois o Senhor a peste a Israel, e morreram de Israel setenta mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 15, 'Mandou também um anjo a Jerusalém, para a assolar; porém quando estava a ser assolada, o Senhor olhou e compadeceu-se dum mal tão grande, e mandou ao anjo exterminador: Basta, retira já a tua mão. O anjo do Senhor estava perto da eira de Ornan Jebuseu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 16, 'Davide, levantando os olhos, viu o anjo do Senhor, que estava entre o céu e a terra, com um a espada desembainhada na sua mão, voltada contra Jerusalém; (à sua vista), tanto ele como os seus anciães, cobertos de cilícios, prostraram-se com os rostos por terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 17, 'Davide disse a Deus: Porventura não sou eu quem mandou fazer o recenseamento do povo? Fui eu que pequei, eu o que fiz o mal; mas este rebanho, que mereceu ele? Volte-se, pois, te peço, Senhor meu Deus, a tua mão contra mim e contra a casa de meu pai, mas que o teu povo não seja castigado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 18, 'O anjo do Senhor mandou a Gad que dissesse a Davide que fosse e que levantasse um altar ao Senhor Deus na eira de Ornan Jebuseu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 19, 'Foi, pois, Davide, conforme a ordem que Gad lhe tinha intimado da parte do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 20, 'Ornan e quatro filhos seus, que com ele estavam, tendo levantado os olhos e visto o anjo, esconderam-se; naquela ocasião estavam debulhando trigo na eira.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 21, 'Quando Davide se dirigia para Ornan, viu-o Ornan, e, saindo da sua eira ao seu encontro, fez-lhe uma profunda reverência, prostrando-se por terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 22, 'Davide disse-lhe: cede-me o sítio da tua eira, para eu edificar nele um altar ao Senhor; cede-me pelo dinheiro que valer para que cesse a praga de cima do povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 23, 'Ornan respondeu a Davide: Toma-a, e o rei senhor faça dela o que for do seu agrado; eu darei também os bois para o holocausto, os trilhos para lenha, e trigo para o sacrifício; darei tudo de boa vontade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 24, 'O rei Davide disse-lhe: Não se fará assim, mas eu te hei-de dar o dinheiro que ela vale, porque eu não devo tirar-te o que é teu, e oferecer assim ao Senhor holocaustos que não me custam nada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 25, 'Deu, pois, Davide a Ornan, pelo terreno, seiscentos siclos de ouro de justo peso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 26, 'Levantou ali um altar ao Senhor, ofereceu holocaustos e hóstias pacíficas e invocou o Senhor, e ele o ouviu, mandando do céu fogo sobre o altar do holocausto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 27, 'Então o Senhor mandou ao anjo, e ele meteu a sua espada na bainha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 28, 'Imediatamente Davide, vendo que o Senhor o tinha ouvido na eira de Ornan Jebuseu, imolou ali vítimas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 29, 'O tabernáculo do Senhor, que Moisés tinha feito no deserto, e o altar dos holocaustos, estavam então no alto de Gabaon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 30, 'Davide não teve força para ir até ao altar, para ali fazer oração a Deus, porque tinha ficado em extremo aterrado de espanto, ao ver a espada do anjo do Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 1, 'Davide disse: Esta é a casa de Deus, e este é o altar para os holocaustos que Israel há-de oferecer,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 2, 'Mandou que se juntassem todos os estrangeiros que havia na terra de Israel e tomou deles os cabouqueiros para cortarem e lavrarem as pedras, a fim de se edificar a casa de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 3, 'Davide preparou também muitíssimo ferro para os pregos das portas e para travar as juntas, e uma quantidade imensa de bronze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 4, 'Eram igualmente inestimáveis as madeiras de cedro, que os Sidónios e os Tírios tinham levado a Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 5, 'Davide disse: Meu filho Salomão é um moço pequeno e tenro; a casa, porém, que eu desejo que se edifique ao Senhor, deve ser tal que seja nomeada em todos os países. Preparar-lhe-ei, pois, para ele o necessário. Por esta razão, antes da sua morte, dispôs todas as coisas precisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 6, 'Depois chamou seu filho Salomão e ordenou-lhe que edificasse a casa do Senhor Deus de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 7, 'Davide disse a Salomão: Meu filho, tive vontade de edificar uma casa ao nome do Senhor meu Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 8, 'O Senhor, porém, falou-me, dizendo: Tu tens derramado muito sangue, tens dado muitas batalhas; tu não poderás edificar uma casa ao meu nome, depois de tanto sangue derramado na minha presença.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 9, 'Nascer-te-á um filho, que será um homem de paz, porque eu o porei em paz com todos os seus inimigos em roda; por esta causa será chamado o Pacífico: eu darei paz e descanso a Israel durante todos os seus dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 10, 'Ele edificará uma casa ao meu nome; ele será meu filho, eu serei seu pai e firmarei o trono do seu reino sobre Israel eternamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 11, 'Agora, pois, o Senhor seja contigo, meu filho, para que prosperes e edifiques uma casa ao Senhor teu Deus, como ele predisse de ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 12, 'O Senhor te dê também prudência e siso, para que possas governar Israel e guardar a lei do Senhor teu Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 13, 'Então poderás prosperar, se guardares os mandamentos e as leis que o Senhor mandou a Moisés que ensinasse a Israel; arma-te de fortaleza e procede varonilmente; não temas nada, nem te desalentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 14, 'Vês que, pelos meus esforços, preparei para os gastos da casa do Senhor cem mil talentos de ouro e um milhão de talentos de prata; o bronze, porém, e o ferro não têm peso, porque a sua quantidade excede todo o cálculo; tenho prontas madeiras e pedras para todas as necessidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 15, 'Tens também muitíssimos operários, canteiros, pedreiros, carpinteiros, e de todas as artes os mais apurados na execução de qualquer tamanho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 16, 'em ouro e em prata, em cobre e em ferro, cujo número é incalculável. Levanta-te, pois, e mete mãos à obra, que o Senhor será contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 17, 'Mandou Davide a todos os chefes de Israel que ajudassem seu filho Salomão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 18, 'Vós vêdes, lhes disse, que o Senhor vosso Deus está convosco, que vos deu a paz por todas as partes, que entregou todos os vossos inimigos nas vossas mãos e que a terra está sujeita diante do Senhor e diante do seu povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 19, 'Disponde, pois, os vossos corações e as vossas almas, para buscardes o Senhor vosso Deus; levantai-vos e edificai o santuário ao Senhor Deus, para que a arca da aliança do Senhor e os vasos consagrados ao Senhor sejam trasladados para a casa que se edificar ao nome do Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 1, 'Achando-se, pois, Davide velho, cheio de dias, constituiu rei sobre Israel a seu filho Salomão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 2, 'Reuniu todos os príncipes de Israel, e os sacerdotes e Levitas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 3, 'Foram contados os Levitas, de trinta anos para cima, e acharam-se trinta e oito mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 4, 'Destes foram escolhidos e distribuídos vinte e quatro mil, para o ministério da casa do Senhor, seis mil para magistrados e juízes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 5, 'quatro mil porteiros e quatro mil para cantarem os louvores do Senhor ao som dos instrumentos que Davide tinha mandado fazer para o canto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 6, 'Davide distribuiu-os segundo as classes dos filhos de Levi, a saber: de Gerson, de Caat e de Merari.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 7, 'Filhos de Gerson foram: Leedan e Semei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 8, 'Filhos de Leedan foram três: Jaiel o chefe, Zetan e Joel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 9, 'Filhos de Semei foram três: Salomit, Hosiel e Aran. Estes foram os chefes das famílias de Leedan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 10, 'Os filhos de Semei foram quatro: Leet, Ziza, Jaus e Baria; estes foram os filhos de Semei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 11, 'Entre eles Leet era o primeiro, Ziza o segundo; Jaus e Baria não tiveram muitos filhos, e, por isso, foram contados numa só família e numa só casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 12, 'Os filhos de Caat foram quatro: Amrão, Isaar, Hebron e Oziel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 13, 'Filhos de Amrão: Aarão e Moisés. Aarão foi separado para servir no Santo dos Santos, ele e seus filhos perpetuamente, para oferecer incenso ao Senhor, segundo o seu rito, e para bem-dizer o seu nome para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 14, 'Os filhos de Moisés, homem de Deus, também foram contados na tribo de Levi.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 15, 'Filhos de Moisés: Gerson e Eliezer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 16, 'Filhos de Gerson: Subuel, o chefe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 17, 'O filho de Eliezer foi Roobia, o chefe. Eliezer não teve outros filhos, mas os filhos de Roobia multiplicaram-se muito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 18, 'Filhos de Isaar: Salomit, o chefe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 19, 'Filhos de Hebron: Jeriau, o primeiro; Amarias, o segundo; Jaaziel, o terceiro; Jecmaão, o quarto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 20, 'Filhos de Oziel: Mica o primeiro; Jesia, o segundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 21, 'Filhos de Merari: Mooli e Musi. Filhos de Mooli: Eleazar e Cis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 22, 'Eleazar morreu, e não teve filhos, mas filhas; estas casaram com os filhos de Cis, seus irmãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 23, 'Os filhos de Musi foram três: Mooli, Heder e Jerimot.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 24, 'Estes são os filhos de Levi, segundo as suas parentelas e famílias, contados um por um, os quais exerciam por turnos as funções do ministério da casa do Senhor, desde os vinte anos para cima.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 25, 'Davide disse: O Senhor Deus de Israel deu paz ao seu povo e habitação em Jerusalém para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 26, 'Para o futuro, os levitas não terão mais que levar o tabernáculo e todos os vasos do seu ministério.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 27, 'Foi segundo as últimas disposições de Davide, que se contou o número dos filhos de Levi, desde os vinte anos para cima.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 28, 'Estavam sujeitos aos filhos de Aarão para o culto da casa do Senhor, nos vestíbulos, nas câmaras, no lugar da purificação, no santuário, e em todas as funções do ministério do templo do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 29, 'Além disso tinham a intendência sobre os pães da proposição, sobre o sacrifício da flor de farinha, sobre os pães ázimos, sobre o que se frita e se assa, e sobre todos os pesos e medidas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 30, 'Os Levitas deviam apresentar-se nela pela manhã a cantar os louvores do Senhor, e do mesmo modo à tarde,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 31, 'tanto na oferenda dos holocaustos oferecidos ao Senhor, como nos dias de sábado e nos dias da lua nova e nas outras solenidades, conforme o número e as cerimônias de cada coisa, continuamente na presença do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 32, 'Deviam observar cuidadosamente as disposições que dizem respeito ao tabernáculo da reunião, ao culto do santuário e à obediência dos filhos de Aarão, seus irmãos, para exercerem as suas funções na casa do Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 1, 'Os filhos de Aarão foram repartidos nestas classes (que se vão enumerar). Os filhos de Aarão foram: Nadab, Ablu, Eleazar e Itamar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 2, 'Nadab e Ablu morreram antes de seu pai, sem deixar filhos; Eleazar e Itamar exerceram as funções do sacerdócio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 3, 'Davide repartiu os filhos de Aarão, isto é, Sadoc dos filhos de Eleazar, Abimelec dos filhos de Itamar, em turnos para o serviço.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 4, 'Porém achou-se que entre os chefes de famílias eram muitos mais os filhos de Eleazar, do que os de Itamar. Fez-se esta divisão: Dezasseis chefes de família para os filhos de Eleazar, e oito chefes de família para os filhos de Itamar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 5, 'Fez-se, por sorte, a repartição de ambas as famílias entre si, porque havia príncipes do santuário e príncipes de Deus, tanto dos filhos de Eleazar como dos filhos de Itamar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 6, 'Semeias, filho de Natanael, da tribo de Levi, secretário, fez o rol deles na presença do rei, dos príncipes, do sacerdote Sadoc, de Aimelec, filho de Abiatar, e diante dos chefes das famílias sacerdotais e levíticas, tirando-se, à sorte, uma família para Eleazar e outra para Itamar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 7, 'A primeira sorte saiu a Joiarib, a segunda a Jedei,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 8, 'a terceira a Harim, a quarta a Seorim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 9, 'a quinta a Melquia, a sexta a Maiman,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 10, 'a sétima a Acos, a oitava a Abia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 11, 'a nona a Jesua, a décima a Sequenias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 12, 'a undécima a Eliasib, a duodécima a Jacim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 13, 'a décima terceira a Hota, a décima quarta a Isbaab,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 14, 'a décima quinta a Belga, a décima sexta a Emer,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 15, 'a décima sétima a Hezir, a décima oitava a Afses,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 16, 'a décima nona a Feteia, a vigésima a Hezequiel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 17, 'a vigésima primeira a Jaquim, a vigésima segunda a Gamul,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 18, 'a vigésima terceira a Dalaiau, a vigésima quarta a Maaziau.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 19, 'Assim se fez a sua distribuição segundo os seus ministérios, para servirem na casa do Senhor, de acordo com as regras estabelecidas por Aarão, seu pai, como tinha mandado o Senhor Deus de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 20, 'Os outros filhos de Levi eram: Subael, dos filhos de Amrão, e Jeedeia dos filhos de Subael;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 21, 'dos filhos de Roobia era chefe Jesias;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 22, 'de Isaari era filho Salemot, e de Salemot era filho Jaat;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 23, 'de Jaat foi filho primogênito Jeriau, Amaria o segundo, Jaaziel o terceiro, Jacmaan o quarto;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 24, 'filho de Oziel foi Mica; filho de Mica foi Samir;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 25, 'irmão de Mica foi Jesia; filho de Jesia foi Zacarias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 26, 'filhos de Meari: Mooli e Musi; filho de Oziau foi Beno;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 27, 'filhos de Merari, por Oziau, foram: Soão, Zacur e Hebri;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 28, 'Mooli teve um filho, isto é, Eleazar, o qual não teve filhos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 29, 'filho de Cis foi Jerameel;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 30, 'filhos de Musi foram: Mooli, Edei e Jerimot. Estes são os filhos de Levi, segundo as casas de suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 31, 'Estes também foram tirados à sorte, com seus irmãos, filhos de Aarão em presença do rei Davide, de Sadoc, de Aimelec e dos chefes das famílias sacerdotais e levíticas, sendo todos, tanto os mais velhos como os mais novos, colocados no mesmo pé de igualdade.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 1, 'Davide e os chefes do exército escolheram para o ministério os filhos de Asaf, de Heman e de Iditun, a fim de tocarem harpa, cítara e címbalos, servindo segundo o seu número no emprego que lhes tinha sido destinado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 2, 'Dos filhos de Asaf: Zacur, José, Natanias, Asarela, filhos de Asaf, sob a direção de Asaf, que cantava junto do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 3, 'Quanto a Iditun, os filhos de Iditun eram: Godolias, Sori, Jeseias, Hasabias, Mataias (e Semei), seis sob a direção de seu pai Iditun, que cantava ao som da cítara, presidindo aos que cantavam e louvavam ao Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 4, 'Quanto a Heman, os filhos de Heman eram: Bociau, Mataniau, Oziel, Subuel, Jerimot, Hananias, Hanani, Eliata, Gedelti, Romentiezer, Jesbacassa, Meloti, Otir, Maaziot.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 5, 'Todos estes eram filhos de Heman, vidente do rei, para cantar louvores de Deus, para exaltar o seu poder. Deus tinha dado a Heman quatorze filhos e três filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 6, 'Todos estavam distribuídos sob a direção de seus pais, isto é, de Asaf, de Iditun e de Heman, para cantarem no templo do Senhor, ao som de címbalos, cítaras e harpas, para exercerem os ministérios da casa do Senhor junto do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 7, 'O número destes, com seus irmãos, todos exercitados em cantar ao Senhor, que ensinavam os cânticos do Senhor, era de duzentos e oitenta e oito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 8, 'Deitaram sortes pelas suas classes, tanto o maior como o menor, tanto o mestre como o discípulo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 9, 'A primeira sorte saiu a José, que era da casa de Asaf. A segunda a Godolias, para ele, para seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 10, 'A terceira a Zacur, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 11, 'A quarta a Izari, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 12, 'A quinta a Natanias, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 13, 'A sexta a Bociau, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 14, 'A sétima a Isreela, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 15, 'A oitava a Jesaia, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 16, 'A nona a Matanias, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 17, 'A décima a Semeias, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 18, 'A undécima a Azareel, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 19, 'A duodécima a Hasabias, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 20, 'A décima terceira a Subael, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 21, 'A décima quarta a Matatia, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 22, 'A décima quinta a Jerimot, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 23, 'A décima sexta a Hananias, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 24, 'A décima sétima a Jesbacasse, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 25, 'A décima oitava a Hanani, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 26, 'A décima nona a Meloti, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 27, 'A vigésima a Eliata, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 28, 'A vigésima primeira a Otir, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 29, 'A vigésima segunda a Gedelti a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 30, 'A vigésima terceira a Maaziot, a seus filhos e irmãos, que eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 31, 'A vigésima quarta a Romemtiezer, a seus filhos e irmãos que eram doze.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 1, 'Eis as classes dos porteiros: Dos Coritas: Maselemia, filho de Coré, dos filhos de Asaf.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 2, 'Os filhos de Masemia foram: Zacarias o primogênito, Jadiel o segundo, Zabadias o terceiro, Jatanael o quarto,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 3, 'Elão o quinto, Joanan o sexto, Elioenal o sétimo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 4, 'Os filhos de Obededom foram: Semeias o primogênito, Jozabad o segundo, Joaa o terceiro, Sacar o quarto, Natanael o quinto,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 5, 'Amiel o sexto, Issacar o sétimo, Folati o oitavo, porque o Senhor o abençoou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 6, 'Semei, seu filho, teve filhos que foram chefes na casa de seu pai, porque eram homens fortíssimos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 7, 'Os filhos de Semeias foram: Otni, Rafael, Obed, Elzabad e seus irmãos, homens fortíssimos; Eliu e Samaquias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 8, 'Todos estes eram da família de Obededom; eles e seus filhos e irmãos, robustíssimos para o seu minsitério, eram (ao todo) sessenta e dois da casa Obededom.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 9, 'Os filhos de Maselemia e seus irmãos, muito valentes, eram dezoito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 10, 'De Hosa, dos filhos de Merari foram: Semri, o chefe - ele não era o primogênito, mas seu pai tinha-o constituído chefe;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 11, 'Helcias o segundo; Tabelias o terceiro; Zacarias, o quarto. Todos os filhos de Hosa e os seus irmãos eram treze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 12, 'Estas classes de porteiros, os seus chefes, como também os seus irmãos, serviam sempre na casa do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 13, 'Deitaram-se sortes pelas suas famílias, sem distinção nem de pequenos nem de grandes, para cada uma das portas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 14, 'A sorte da porta do oriente caiu a Selemias. A Zacarias, seu filho, homem prudentíssimo e habilíssimo, coube em sorte a (porta) do setentrião.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 15, 'A do meio-dia caiu a Obededom e seus filhos; nesta parte da casa estava o conselho dos anciães.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 16, 'A Sefim e Hosa caiu a do ocidente. Junto da porta que dá para a estrada da subida; uma guarda estava defronte de outra guarda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 17, 'Ao oriente havia seis Levitas, e ao setentrião quatro por dia; ao meio-dia, do mesmo modo, quatro por dia; onde estava o conselho, outros quatro, dois a dois.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 18, 'Nas celas dos porteiros, ao ocidente, estavam quatro no caminho, e dois nas dependências.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 19, 'Foi esta a distribuição dos porteiros, filhos de Coré e de Merari.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 20, 'Os levitas, seus irmãos, tinham a guarda dos tesouros da casa de Deus e dos vasos sagrados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 21, 'De entre os filhos de Dedan, isto é, os filhos de Gerson descendentes de Ledan, chefes das famílias de Dedan, gersonita, estava Jeieli.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 22, 'Os filhos de Jeieli, Zatan e Joel, seu irmão, eram guardas dos tesouros da casa do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 23, 'De entre as famílias de Amrão, de Isaar, de Hebron e de Oziel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 24, 'estava Snbael, filho de Gerson, filho de Moisés, que era o superintendente dos tesouros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 25, 'De entre os seus irmãos, descendentes de Eliezer, cujo filho foi Raabia, cujo filho foi Isaías, cujo filho foi Jorão, cujo filho foi Zecri, cujo filho foi Selemit,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 26, 'este mesmo Selemit e seus irmãos tinham a intendência dos tesouros das coisas santas, que o rei Davide e os chefes das famílias, os chefes de milhar, os centuriões e os chefes do exército tinham consagrado:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 27, 'coisas que tinham consagrado, provenientes dos despojos das guerras para a construção e alfaias do templo do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 28, 'Todas as coisas consagradas por Samuel, o vidente, por Saul, filho de Cis, por Abner, filho de Ner, e Joab, filho de Sarvia, todas estavam confiadas à guarda de Selemit e de seus irmãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 29, 'Os descendentes de Isaar, Conenias e seus filhos, cuidavam dos negócios de fora, que diziam respeito a Israel, (desempenhando o papel de) escribas e magistrados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 30, 'Hasabias, da família de Hebron, e seus irmãos, homens muito fortes, em número de mil e setecentos, governavam os Israelitas além do Jordão para o ocidente, em todas as coisas pertencentes ao serviço do Senhor e do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 31, 'Jerias foi chefe dos Hebronitos, segundo as suas famílias e ramos; no ano quadragésimo do reinado de Davide fez-se o recenseamento deles, e acharam-se em Jazer de Galaad homens fortíssimos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 32, 'dos irmãos de Jerias, no vigor da idade, acharam-se dois mil e setecentos chefes de famílias. O rei Davide deu-lhes o mando sobre os Rubenitas, os Gaditas e sobre a meia tribo de Manassés, no que dizia respeito ao serviço de Deus e do rei.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 1, 'Os filhos de Israel que, segundo o seu número, com os chefes de famílias, os chefes de milhar, os centuriões e oficiais, serviam ao rei, distribuídos pelas suas turmas, entrando e saindo todos os meses do ano (isto é, prestando serviço um mês) eram (em cada mês) vinte e quatro mil homens com andados pelos seus respectivos capitães.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 2, 'A primeira divisão para o primeiro mês era comandada por Jesboão, filho de Zabdiel, e ficavam às suas ordens vinte e quatro mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 3, 'Era da casa de Farés, e o primeiro entre todos os comandantes do exército durante o primeiro mês.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 4, 'Dudia Aoita comandava a divisão do segundo mês e tinha às suas ordens outro, chamado Macelot, que comandava uma parte dos vinte e quatro mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 5, 'O chefe da terceira divisão, no terceiro mês, era o sacerdote Banaias, filho de Jojada: na sua divisão havia vinte e quatro mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 6, 'Este é aquele Banaias o mais valente dentre os trinta, e superior aos trinta; seu filho Amizabad, comandava (como seu subalterno) a divisão que lhe estava subordinada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 7, 'O quarto chefe, no quarto mês, era Asael, irmão de Joab, e depois dele Zabadias, seu filho; na sua divisão havia vinte e quatro mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 8, 'O quinto chefe, no quinto mês, era Samaot de Jezer: na sua divisão havia vinte e quatro mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 9, 'O sexto, no sexto mês, era Hira, filho de Acés de Tecua; na sua divisão havia vinte e quatro mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 10, 'O sétimo, no sétimo mês, era Heles de Faloni, da tribo de Efraim; na sua divisão havia vinte e quatro mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 11, 'O oitavo, no oitavo mês, era Sobocal de Husat, da estirpe de Zaral; na sua divisão havia vinte e quatro mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 12, 'O nono, no nono mês, era Abiezer de Anatot, dos filhos de Jemini; na sua divisão havia vinte e quatro mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 13, 'O décimo, no décimo mês, era Marai de Netofat, descendente de Zaral; na sua divisão havia vinte e quatro mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 14, 'O undécimo, no undécimo mês, era Banais, de Faraton, da tribo de Efraim; na sua divisão havia vinte e quatro mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 15, 'O duodécimo, no duodécimo mês, era Holdai de Netofat, descendente de Gotoniel; na sua divisão havia vinte e quatro mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 16, 'As tribos de Israel tinham os seus chefes: Da de Ruben era chefe Eliezer filho de Zecri; da de Simeão, Safatias, filho de Maaca;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 17, 'da de Levi era chefe Hasabias, filho de Camuel; da de Arão era chefe Sadoc;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 18, 'da de Judá era chefe Eliu, irmão de Davide; da de Issacar era chefe Amri, filho de Miguel;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 19, 'da de Zabulon era chefe Jesmaias, filho de Abdias: da de Neftali era chefe Jerimot, filho de Ozriel;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 20, 'da meia tribo de Efraim era chefe Osee, filho de Ozaziu; da meia tribo de Manassés era chefe Joel, filho de Fadala;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 21, 'da outra meia tribo de Manassés, em Galaad, era chefe Jado, filho de Zacarias; da de Benjamim era chefe Jasiel, filho de Abner;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 22, 'da de Dan era chefe Ezriel, filho de Jeroão. Estes eram os chefes dos filhos de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 23, 'Não quis, porém, Davide contar os que tinha menos de vinte anos, porque o Senhor tinha dito que multiplicaria Israel como as estrelas do céu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 24, 'Joab, filho de Sarvia, tinha começado a fazer o recenseamento, mas não o acabou, porque, por causa disto, a ira de Deus tinha caído sobre Israel; por isso o número dos que estavam já contados não foi referido nos fastos do rei Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 25, 'O tesoureiro-mór do rei era Azmot filho de Adiel; o intendente dos tesouros, que havia nas cidades, nas vilas e nos castelos, era Jonatan, filho de Ozias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 26, 'Ezri filho de Quelub, era o superintendente da agricultura e dos lavradores que cultivavam as terras;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 27, 'Semeias de Romati era o das vinhas: Zabdias de Afoni, era das adegas:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 28, 'Balanan de Geder cuidava dos olivais e figueirais que estavam nos campos; Joás dos armazéns de azeite;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 29, 'dos rebanhos que pastavam no campo de Saron, cuidava Setrai Saronita: dos bois, que se criavam nos vales, Safat, filho de Adli:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 30, 'Ubli Ismaelita cuidava dos camelos: Jadias de Meronat, dos jumentos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 31, 'Jaziz Agareu, das ovelhas. Todos estes eram os intendentes da fazenda do rei Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 32, 'Jonatan, tio paterno de Davide, homem prudente e letrado, era seu conselheiro; ele e Jaiel, filho de Hacamoni, estavam com os filhos do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 33, 'Aquitofel era conselheiro do rei; Ousai Araquita era amigo do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 34, 'Depois de Aquitofel, foram Jojada, filho de Banaias, e Ablatar. Joab era o generalíssimo do exército do rei.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 1, 'Convocou Davide em Jerusalém todos os príncipes de Israel, os chefes das tribos, os chefes das divisões que serviam o rei, e também os chefes de milhar e centuriões, os administradores da fazenda e possessões do rei e de seus filhos, assim como os eunucos e os mais poderosos e valorosos do exército.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 2, 'Tendo-se o rei levantado e posto em pé, disse: Ouvi-me, irmãos meus e povo meu: Eu tinha intenção de edificar uma casa de repouso para a arca da aliança do Senhor e o escabelo dos pés do nosso Deus, e tenho preparado tudo o necessário para a construção do edifício.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 3, 'Deus, porém, disse-me: Tu não edificarás uma casa ao meu nome, porque és um homem guerreiro, tens derramado sangue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 4, 'Todavia o Senhor Deus de Israel escolheu-me dentre toda a casa de meu pai, para me fazer rei de Israel para sempre, porque de Judá escolheu os príncipes, e da casa de Judá escolheu a casa de meu pai, e entre os filhos de meu pai, dignou-se escolher-me a mim, para me constituir rei sobre todo o Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 5, 'E até dentre os meus filhos (porque o Senhor deu-me muitos filhos) escolheu o meu filho Salomão, para se sentar no trono do reino do Senhor sobre Israel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 6, 'e disse-me: Teu filho Salomão edificará a minha casa e os meus átrios, porque eu o escolhi para meu filho, e eu serei seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 7, 'Firmarei para sempre o seu reino, se perseverar em cumprir os meus preceitos e as minhas leis, como ele o faz ao presente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 8, 'Agora, na presença de todo o ajuntamento de Israel, ouvindo o nosso Deus (eu digo); Guardai e estudai todos os mandamentos do Senhor, nosso Deus, a fim de possuirdes esta terra cheia de bens e de a deixardes para sempre a vossos filhos, depois de vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 9, 'E tu, meu filho Salomão, conhece o Deus de teu pai, serve-o com um coração perfeito e uma plena vontade, porque o Senhor sonda todos os corações e penetra todos os pensamentos do espírito. Se tu o buscares, ele se deixará encontrar por ti, mas, se o deixares, ele te rejeitará para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 10, 'Agora, pois, já que o Senhor te escolheu para edificares a casa do santuário, anima-te e completa a obra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 11, 'Davide deu a Salomão, seu filho, o desenho do pórtico e do templo, das suas oficinas, das suas salas, dos seus aposentos interiores, da casa da propiciação,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 12, 'e também o de todos os átrios que ele tinha mentalmente delineado, e o dos quartos que devia haver em roda para os tesouros da casa do Senhor, para os depósitos das coisas consagradas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 13, 'para as classes dos sacerdotes e dos Levitas, para toda a obra do serviço da casa do Senhor, e para todos os vasos consagrados ao serviço do templo do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 14, '(Deu-lhe) o modelo dos utensílios de ouro, com o peso que devia ter cada um dos vasos do ministério. Também especificou o peso da prata, segundo a diversidade dos vasos e dos feitios, de que deu o modelo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 15, 'E para os candeeiros de ouro, e para as suas lâmpadas deu também o peso do ouro, segundo o tamanho de cada candeeiro e das lâmpadas. Do mesmo modo, para os candeeiros de prata e para as suas lâmpadas, deu o peso de prata, segundo a diversidade dos tamanhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 16, 'Deu também o peso do ouro para as mesas dos pães da proposição, segundo a diversidade das mesas, e igualmente o peso da prata para outras mesas de prata.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 17, 'Também deu o modelo para os garfos, copos, turíbulos de ouro puríssimo, para os leõezinhos de ouro, segundo os seus tamanhos, e destinou o peso de ouro para cada um dos leõezinhos. Do mesmo modo para os leões de prata determinou o peso da prata.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 18, 'E para o altar, em que se queima o incenso, deu do ouro mais fino, para que dele se fizesse a figura dum carro de querubins, que estendessem as suas asas, e cobrissem a arca da aliança do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 19, 'Todas estas coisas, disse o rei, todas as obras deste modelo me foram dadas escritas pela mão de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 20, 'Disse mais Davide a seu filho Salomão: Procede varonilmente, anima-te e mete mãos à obra; não temas nada, não desanimes, porque, o Senhor meu Deus será contigo, não te abandonará, nem te desamparará, até que tenhas concluído toda a obra para o serviço da casa do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 21, 'Eis as classes dos sacerdotes e dos Levitas, que estão diante de ti, e estão prontos para todo o serviço da casa do Senhor, e assim os chefes como o povo saberão executar todas as tuas ordens.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 1, 'O rei disse a toda a assembleia: Deus escolheu um só, o meu filho Salomão, que é jovem e tenro; a empresa é grande, porque não se prepara a morada para um homem, mas para Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 2, 'Eu, pois, com todas as minha forças preparei o que era necessário para as despesas da casa do meu Deus: ouro para os vasos de ouro, prata para os de prata, bronze para as obras de bronze, ferro para as de ferro, madeira para as de madeira; preparei também pedras de ónix, e pedras semelhantes ao alabastro, e de diversas cores, toda a casta de pedras preciosas e mármores de Paros em grandíssima quantidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 3, 'Além destas coisas, que ofereci para a casa do meu Deus, dou do meu pecúlio o ouro e a prata para o templo do meu Deus, sem falar do que preparei para o santuário:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 4, 'três mil talentos de ouro de Ofir, e sete mil talentos de prata finíssima para revestimento das paredes do templo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 5, 'Desta sorte, quando seja preciso ouro, façam-se de ouro as obras, quando for preciso a prata, façam-se de prata as obras pelas mãos dos artistas. Se alguém, por sua vontade, oferecer alguma coisa ao Senhor, encha hoje as suas mãos e ofereça ao Senhor o que bem lhe parecer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 6, 'Fizeram ofertas voluntàriamente os chefes das famílias, os nobres das tribos de Israel, os chefes de milhar, os centuriões e os intendentes da fazenda do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 7, 'Deram para as obras da casa de Deus cinco mil talentos de ouro, e dez mil dáricos; dez mil talentos de prata, dezoito mil talentos de cobre, e cem mil talentos de ferro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 8, 'Todos os que tinham pedras preciosas, deram-nas para os tesouros da casa do Senhor, por mão de Jaiel Gersonita.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 9, 'O povo alegrou-se, ao fazer estas oferendas voluntárias, porque as fazia de todo o seu coração ao Senhor; o rei Davide da mesma sorte se alegrou em extremo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 10, 'e louvou o Senhor diante de toda esta multidão, dizendo: Bem-dito és tu, ó Senhor Deus de Israel, nosso pai, de eternidade em eternidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 11, 'Tua é, Senhor, a grandeza, o poder, honra, majestade e porque tudo o que há no céu e na terra, é teu; teu é, Senhor, o império, e tu estás acima de todos os príncipes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 12, 'Tuas são as riquezas, tua é a glória; tu és o dominador de tudo, na tua mão está a fortaleza e o poder; na tua mão está o dar grandeza e solidez a todas as coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 13, 'Agora, pois, ó Deus nosso, nós te louvamos e celebramos o teu nome glorioso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 14, 'Quem sou eu, e quem é o meu povo, para te podermos oferecer todas estas coisas? Tudo é teu, e o que recebemos da tua mão, isso mesmo te oferecemos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 15, 'Nós somos peregrinos e estrangeiros diante de ti, como todos os nossos pais. Os nossos dias são como a sombra sobre a terra, e não há consistência alguma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 16, 'Senhor nosso Deus, toda esta riqueza, que juntamos para se edificar uma casa ao teu santo nome, veio da tua mão, e todas as coisas são tuas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 17, 'Eu sei, Deus meu, que sondas os corações e que amas a simplicidade, e por isso eu também te ofereci alegre todas estas coisas, na simplicidade do meu coração, e vi que o teu povo, que aqui está reunido, te ofereceu os seus presentes com grande alegria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 18, 'Senbor Deus de nossos pais Abraão, Isaac e Israel, conserva eternamente este afeto no coração do teu povo, e encaminha para ti o seu coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 19, 'Dá também a meu filho Salomão um coração perfeito, para que guarde os teus mandamentos, as tuas leis e as tuas cerimônias, cumpra tudo, e edifique a casa, para a qual fiz preparativos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 20, 'Depois disto, Davide disse a todo o ajuntamento: Bem-dizei o Senhor nosso Deus. E todo o povo bem-disse o Senhor Deus de seus pais, prostrando-se e adorando a Deus, e em seguida (prestando as suas homenagens) ao rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 21, 'Imolaram vítimas ao Senhor, e, no dia seguinte, ofereceram em holocausto mil touros, mil carneiros, mil cordeiros, com as suas libações ordinárias e muitos outros sacrifícios por todo o Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 22, 'E comeram e beberam naquele dia diante do Senhor, com grande regozijo. Ungiram segunda vez Salomão, filho de Davide. Ungiram-no diante do Senhor como rei, e a Sadoc como pontífice.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 23, 'Salomão sentou-se no trono do Senhor, como rei em lugar de Davide, seu pai; agradou a todos, e todo o Israel lhe rendeu obediência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 24, 'Todos os príncipes, todos os grandes, mesmo todos os filhos do rei Davide juraram fidelidade e submeteram-se ao rei Salomão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 25, 'O Senhor elevou Salomão sobre todo o Israel e deu-lhe no seu reinado tal glória, qual antes dele não teve nenhum rei de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 26, 'Davide, filho de Isaf, assim reinou sobre todo o Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 27, 'O tempo que reinou sobre Israel foi de quarenta anos: em Hebron reinou sete anos, e em Jerusalém trinta e três anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 28, 'Morreu numa ditosa velhice, cheio de dias, de bens e de glória. Salomão seu filho reinou em lugar dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 29, 'As ações do rei Davide, desde as primeiras às últimas, estão escritas no livro de Samuel, o vidente, no livro do profeta Natan e no volume de Gad, o vidente,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 30, 'com tudo o que ocorreu no seu reinado, o seu poder e as vicissitudes por que passou, assim como Israel e todos os reinos da terra.');
